        if idx < 0:
            return initial
        return transitions[idx][1]

    def resolve(w, fold):
        candidates = []
        # Check before first transition
        if n == 0:
            x = w - initial
            candidates.append(x)
        else:
            first_t = transitions[0][0]
            x = w - initial
            if x < first_t:
                candidates.append(x)

