            last_t, last_off = transitions[-1]
            x = w - last_off
            if x >= last_t:
                candidates.append(x)

        # Check each transition for possible candidates
        for i in range(n):
            t, off = transitions[i]
            prev_off = initial if i == 0 else transitions[i-1][1]
            # Candidate before transition
            x_before = w - prev_off
            if x_before < t:
                candidates.append(x_before)
            # Candidate after transition
            x_after = w - off
            if x_after >= t:
                if i < n-1:
                    next_t = transitions[i+1][0]
                    if x_after < next_t:
                        candidates.append(x_after)
                else:
                    candidates.append(x_after)

