        candidates = list(set(candidates))
        valid = []
        for x in candidates:
            off_x = get_offset(x)
            if x + off_x == w:
                valid.append(x)
        if len(valid) == 0:
            # Handle gap case
            for i in range(n):
                t, off = transitions[i]
                prev_off = initial if i ==0 else transitions[i-1][1]
                if prev_off > off:  # transition caused a decrease (clocks back)
                    if t + off <= w < t + prev_off:
                        a = prev_off
                        b = off
                        return (w - a) if fold ==0 else (w - b)
