def table_zone_eval(zone, ops):
    initial, transitions = zone
    transitions = list(transitions)
    n = len(transitions)
    times = [t for t, off in transitions]

    def get_offset(x):
        idx = bisect.bisect_right(times, x)
        if idx == 0:
            return initial
        else:
            return transitions[idx-1][1]

    def find_matches(w):
        candidates = []
        # Check initial interval
        o = initial
        x_candidate = w - o
        if n == 0:
            candidates.append(x_candidate)
        else:
            t0 = times[0]
            if x_candidate < t0:
                candidates.append(x_candidate)

        # Check each transition's interval
        for i in range(n):
            t_prev = times[i]
            o = transitions[i][1]
            x_candidate = w - o
            if i < n - 1:
                t_next = times[i+1]
            else:
                t_next = float('inf')
            if t_prev <= x_candidate < t_next:
                candidates.append(x_candidate)

        # Check the last interval (after last transition)
        if n > 0:
            o = transitions[-1][1]
            x_candidate = w - o
            t_prev = times[-1]
            if x_candidate >= t_prev:
                candidates.append(x_candidate)

        # Now verify each candidate
        matches = []
        for x in candidates:
            actual_offset = get_offset(x)
            if x + actual_offset == w:
                matches.append(x)
        return matches

    def resolve(w, fold):
        matches = find_matches(w)
        if len(matches) == 1:
            return matches[0]
        elif len(matches) == 0:
            # Find the gap's transition
            for i in range(n):
                t = transitions[i][0]
                new_off = transitions[i][1]
                if i == 0:
                    prev_off = initial
                else:
                    prev_off = transitions[i-1][1]
                a = prev_off
                b = new_off
                if a < b:
                    if t + a <= w < t + b:
                        if fold == 0:
                            return w - a
                        else:
                            return w - b
            raise ValueError("Invalid zone")
        elif len(matches) == 2:
            matches.sort()
            if fold == 0:
                return matches[0]
            else:
                return matches[1]
        else:
            raise ValueError("Unexpected number of matches")

    results = []
    for op in ops:
        if not isinstance(op, (list, tuple)) or len(op) < 1:
            raise ValueError("Invalid operation")
