                raise ValueError("Wrong number of items for wall")
            x = op[1]
            if not isinstance(x, int):
                raise ValueError("Invalid parameters for wall")
            offset = get_offset(x)
            w = x + offset
            matches = find_matches(w)
            matches.sort()
            if len(matches) == 2:
                if x == matches[1]:
                    f = 1
                else:
                    f = 0
            else:
                f = 0
            results.append((w, f))
        elif op_name == "add":
            if len(op) != 5:
                raise ValueError("Wrong number of items for add")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if not all(isinstance(v, int) for v in [w, fold, days, secs]) or fold not in (0, 1):
                raise ValueError("Invalid parameters for add")
            w2 = w + days * 86400
            x1 = resolve(w2, fold)
            x2 = x1 + secs
            offset = get_offset(x2)
            w_result = x2 + offset
            matches = find_matches(w_result)
            matches.sort()
            if len(matches) == 2:
                if x2 == matches[1]:
                    f = 1
                else:
                    f = 0
            else:
                f = 0
            results.append((w_result, f))
        else:
            raise ValueError("Unknown operation")

    return results

