import sys
from datetime import date

def validate_leaps(leaps):
    if not isinstance(leaps, (list, tuple)):
        raise ValueError("invalid leaps")
    if len(leaps) > 100:
        raise ValueError("invalid leaps")
    prev_y, prev_m = 1969, 12
    for leap in leaps:
        if not isinstance(leap, (list, tuple)) or len(leap) != 3:
            raise ValueError("invalid leap entry")
        y, m, d = leap
        if not isinstance(y, int) or not isinstance(m, int) or not isinstance(d, int):
            raise ValueError("invalid leap entry")
        if y < 1970 or y > 2400:
            raise ValueError("invalid year")
        if m < 1 or m > 12:
            raise ValueError("invalid month")
        if d not in (-1, 1):
            raise ValueError("invalid delta")
        if (y, m) <= (prev_y, prev_m):
            raise ValueError("invalid order")
        if (y, m) == (1970, 1):
            raise ValueError("invalid leap at 1970-01")
        prev_y, prev_m = y, m
    return True

def smear_info(leaps):
    leap_data = []
    cumulative_delta = 0
    epoch = date(1970, 1, 1)
    for y, m, delta in leaps:
        next_m = m + 1 if m < 12 else 1
        next_y = y if m < 12 else y + 1
        next_day = date(next_y, next_m, 1)
        D_k = (next_day - epoch).days
        cumulative_delta += delta
        E_k = 86400000 * D_k + 1000 * cumulative_delta
        leap_data.append((E_k, delta))
    return leap_data

def smeared_ms(n, leaps):
    if not isinstance(n, int) or n < 0 or n > 10**16:
        raise ValueError("invalid n")
    validate_leaps(leaps)
    leap_data = smear_info(leaps)
    total_offset = 0
    for E, delta in leap_data:
        start = E - 1000000
        if n < start:
            g = 0
        elif n >= E:
            g = 1000
        else:
            g = (n - start) // 1000
        total_offset += delta * g
    return n - total_offset

def unsmeared_ms(s, leaps):
    if not isinstance(s, int) or s < 0 or s > 10**16:
        raise ValueError("invalid s")
    validate_leaps(leaps)
    leap_data = smear_info(leaps)

    # Determine the maximum possible offset from all leaps
    max_offset = 1000 * len(leap_data)
    low = 0
    high = s + max_offset
    high = min(high, 10**16)

    best_n = None
    while low <= high:
        mid = (low + high) // 2
        current_s = smeared_ms(mid, leaps)
        if current_s < s:
            low = mid + 1
        elif current_s > s:
            high = mid - 1
        else:
            best_n = mid
            high = mid - 1  # Search for the smallest n

    if best_n is None:
        raise ValueError("no solution")

    # Verify that the found n indeed gives s
    # Also check if there's a lower n that also works (due to plateau)
    # Since we already search for the smallest, best_n should be correct
    return best_n

