def petri_starts(places, transitions, until, limit):
    # Input validation
    if not isinstance(places, dict):
        raise ValueError("places must be a dict")
    for name, count in places.items():
        if not isinstance(name, str) or not name:
            raise ValueError("place names must be non-empty strings")
        if not isinstance(count, int) or count < 0 or count > 10**6:
            raise ValueError("place counts must be integers between 0 and 1e6")

    if not isinstance(transitions, (list, tuple)):
        raise ValueError("transitions must be a list or tuple")
    trans_list = []
    trans_names = set()
    for t in transitions:
        if not isinstance(t, tuple) or len(t) != 6:
            raise ValueError("each transition must be a 6-tuple")
        name, inputs, outputs, duration, priority, servers = t
        if not isinstance(name, str) or not name:
            raise ValueError("transition names must be non-empty strings")
        if name in trans_names:
            raise ValueError("transition names must be unique")
        trans_names.add(name)
        if not isinstance(inputs, dict) or not inputs:
            raise ValueError("inputs must be a non-empty dict")
        for p, w in inputs.items():
            if p not in places:
                raise ValueError(f"input place {p} not in places")
            if not isinstance(w, int) or w < 1 or w > 1000:
                raise ValueError("input weights must be integers 1..1000")
        if not isinstance(outputs, dict):
            raise ValueError("outputs must be a dict")
        for p, w in outputs.items():
            if p not in places:
                raise ValueError(f"output place {p} not in places")
            if not isinstance(w, int) or w < 1 or w > 1000:
                raise ValueError("output weights must be integers 1..1000")
        if not isinstance(duration, int) or duration < 0 or duration > 10**12:
            raise ValueError("duration must be an integer 0..1e12")
        if not isinstance(priority, int):
            raise ValueError("priority must be an integer")
        if not isinstance(servers, int) or servers < 1 or servers > 10**6:
            raise ValueError("servers must be an integer 1..1e6")
        trans_list.append(t)

    if not isinstance(until, int) or until < 0 or until > 10**12:
        raise ValueError("until must be an integer 0..1e12")
    if not isinstance(limit, int) or limit < 1 or limit > 2000:
        raise ValueError("limit must be an integer 1..2000")

    # Initialize variables
    current_time = 0
    tokens = dict(places)
    active_count = {t[0]: 0 for t in trans_list}
    in_progress = []
    result = []
    trans_names_list = [t[0] for t in trans_list]
    trans_dict = {t[0]: t for t in trans_list}

    while True:
        # Process completions at current_time
        completions = []
        for item in in_progress:
            if item[0] == current_time:
                completions.append(item)
        # Remove completed items from in_progress
        new_in_progress = []
        for item in in_progress:
            if item not in completions:
                new_in_progress.append(item)
        in_progress = new_in_progress

        # Process outputs of completed transitions
        for c in completions:
            name = c[1]
            trans = trans_dict[name]
            outputs = trans[2]
            for place, weight in outputs.items():
                tokens[place] += weight
            active_count[name] -= 1

        # Process starts
        started = True
        while started:
            started = False
            enabled = []
            for trans in trans_list:
                name = trans[0]
                inputs = trans[1]
                servers = trans[5]
                if active_count[name] >= servers:
                    continue
                valid = True
                for p, w in inputs.items():
                    if tokens[p] < w:
                        valid = False
                        break
                if valid:
                    enabled.append(trans)
            if not enabled:
                break
            # Sort enabled by priority, then by their order in trans_list
            enabled_sorted = sorted(enabled, key=lambda t: (t[4], trans_list.index(t)))
            selected = enabled_sorted[0]
            # Subtract inputs
            name = selected[0]
            inputs = selected[1]
            duration = selected[3]
            outputs = selected[2]
            for p, w in inputs.items():
                tokens[p] -= w
            # Record start
            result.append( (current_time, name) )
            if len(result) >= limit:
                return result
            # Update active_count and in_progress
            if duration == 0:
                # Add outputs immediately
                for p, w in outputs.items():
                    tokens[p] += w
            else:
                completion_time = current_time + duration
                in_progress.append( (completion_time, name) )
                active_count[name] += 1
            started = True

        # Check next time
        if not in_progress:
            break
        next_time = min( ctime for (ctime, _) in in_progress )
        if next_time > until:
            break
        current_time = next_time

    return result

