from collections import defaultdict

def gate_trace(gates, stimuli, watch, until):
    # Validate all inputs and check for cycles

    # Step 1: Collect all outputs and check for uniqueness
    outputs = set()
    gate_outputs = [gate[0] for gate in gates]
    for out in gate_outputs:
        if out in outputs:
            raise ValueError("Duplicate gate outputs")
        outputs.add(out)

    # Step 2: Collect all signals (outputs and inputs)
    all_signals = set()
    for gate in gates:
        all_signals.add(gate[0])
        for s in gate[2]:
            all_signals.add(s)

    # Step 3: Determine primary inputs (signals in inputs but not outputs)
    primary_inputs = set()
    for gate in gates:
        for s in gate[2]:
            if s not in outputs:
                primary_inputs.add(s)

    # Step 4: Check stimuli signals are primary inputs
    for s in stimuli:
        if s[1] not in primary_inputs:
            raise ValueError("Stimulus signal is not a primary input")

    # Step 5: Check watch signals are known
    for w in watch:
        if w not in all_signals:
            raise ValueError("Unknown watch signal")

    # Step 6: Check for cycles in dependency graph
    # Build adjacency list
    graph = defaultdict(list)
    for gate in gates:
        out = gate[0]
        ins = gate[2]
        for s in ins:
            graph[s].append(out)

    # Check for cycles using DFS
    visited = {node: False for node in all_signals}
    rec_stack = {node: False for node in all_signals}

    def has_cycle(node):
        visited[node] = True
        rec_stack[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                if has_cycle(neighbor):
                    return True
            elif rec_stack[neighbor]:
                return True
        rec_stack[node] = False
        return False

    for node in all_signals:
        if not visited[node]:
            if has_cycle(node):
                raise ValueError("Cycle detected in the dependency graph")

    # Step 7: Check for any gate with invalid inputs (shouldn't happen per problem statement)
    # Proceed to simulation

    # Prepare the stimuli grouped by time
    stimuli_dict = defaultdict(list)
    for time, signal, value in stimuli:
        stimuli_dict[time].append((signal, value))
    # Collect all stimulus times and sort them
    stimulus_times = sorted(stimuli_dict.keys())

    # Initialize data structures
    current_values = {s: 0 for s in all_signals}
    pending_assignments = {}  # key: signal, value: (due_time, value)
    traces = {w: [] for w in watch}
    previous_values = {w: 0 for w in watch}

    # Priority queue for events. Each element is (time, type, data)
    # We can represent events as (time, 'stim', (signal, value)), (time, 'assign', (signal, value))
    # But perhaps better to handle stimuli and assignments separately.
    # Alternatively, use a heap that contains all the times when events happen
    heap = []
    for t in stimulus_times:
        heapq.heappush(heap, t)

    # Also, track all assignment due times
    # But assignments are generated dynamically
    # The main loop will process each time in order

    # The main simulation loop
    while heap:
        current_time = heapq.heappop(heap)
        if current_time > until:
            continue

        # Process stimuli at current_time
        changed_in_batch = set()
        # Apply stimuli in list order (later ones override)
        for s, v in stimuli_dict[current_time]:
            if current_values[s] != v:
                changed_in_batch.add(s)
                current_values[s] = v

        # Apply pending assignments due at current_time
        # Collect all signals with pending assignments due now
        to_assign = []
        for sig in list(pending_assignments.keys()):
            due_time, val = pending_assignments[sig]
            if due_time == current_time:
                to_assign.append(sig)

        for sig in to_assign:
            due_time, val = pending_assignments.pop(sig)
            if current_values[sig] != val:
                changed_in_batch.add(sig)
                current_values[sig] = val

        # Now evaluate gates in rounds until no assignments are due at current_time
        # Track the signals that changed in this round
        changed_in_round = changed_in_batch.copy()
        while True:
            # Collect gates to evaluate this round
            gates_to_evaluate = []
            for gate in gates:
                out, op, ins, delay = gate
                # Check if any input has changed in the previous round
                for s in ins:
                    if s in changed_in_round:
                        gates_to_evaluate.append(gate)
                        break
            # Process all gates_to_evaluate
            new_assignments = []
            for gate in gates_to_evaluate:
                out, op, ins, delay = gate
                # Remove any pending assignment for this gate's output
                if out in pending_assignments:
                    del pending_assignments[out]

                # Compute new value
                in_values = [current_values[s] for s in ins]
                if op == 'AND':
                    new_val = 1
                    for v in in_values:
                        new_val &= v
                elif op == 'OR':
                    new_val = 0
                    for v in in_values:
                        new_val |= v
                elif op == 'XOR':
                    new_val = sum(in_values) % 2
                elif op == 'NAND':
                    new_val = 1
                    for v in in_values:
                        new_val &= v
                    new_val = 1 - new_val
                elif op == 'NOR':
                    new_val = 0
                    for v in in_values:
                        new_val |= v
                    new_val = 1 - new_val
                elif op == 'NOT':
                    new_val = 1 - in_values[0]
                elif op == 'BUF':
                    new_val = in_values[0]
                else:
                    raise ValueError("Invalid operation")

                if new_val != current_values[out]:
                    # Queue the new assignment
                    new_due_time = current_time + delay
                    # Check if there's already a pending assignment
                    # (but we already removed it)
                    # So we can queue this new one
                    pending_assignments[out] = (new_due_time, new_val)
                    if new_due_time not in [e[0] for e in heap]:
                        heapq.heappush(heap, new_due_time)
                    new_assignments.append(out)

            # Check if any assignments were queued due at current_time
            has_more = any(
                pending_assignments[sig][0] == current_time for sig in pending_assignments
            )
            if not has_more:
                break
            changed_in_round = set(new_assignments)

        # Now, after all rounds, record the changes in the watched signals
        for w in watch:
            new_val = current_values[w]
            if new_val != previous_values[w]:
                traces[w].append((current_time, new_val))
                previous_values[w] = new_val

