    graph = defaultdict(list)
    for gate in gates:
        out = gate[0]
        ins = gate[2]
        for s in ins:
            graph[s].append(out)

    # Check for cycles with DFS
    visited = {node: False for node in all_signals}
    rec_stack = {node: False for node in all_signals}

    def has_cycle(node):
        visited[node] = True
        rec_stack[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                if has_cycle(neighbor):
                    return True
            elif rec_stack[neighbor]:
                return True
        rec_stack[node] = False
        return False

    for node in all_signals:
        if not visited[node]:
            if has_cycle(node):
                raise ValueError("Cycle detected in the dependency graph")

    # Prepare stimuli grouped by time
    stimuli_dict = defaultdict(list)
    for time, signal, value in stimuli:
        stimuli_dict[time].append((signal, value))
    stimulus_times = sorted(stimuli_dict.keys())

