            return
        if signal in pending_assignments:
            old_due, old_val = pending_assignments[signal]
            if old_due < due_time:
                return  # new assignment is later, so ignore
        pending_assignments[signal] = (due_time, value)
        add_to_heap(due_time)

    while heap:
        current_time = heapq.heappop(heap)
        if current_time > until:
            continue
        pending_times.discard(current_time)

