            del pending_assignments[sig]
            if current_values[sig] != val:
                changed_in_batch.add(sig)
                current_values[sig] = val

        # Evaluate gates in rounds until no assignments due at current_time
        changed_in_round = changed_in_batch.copy()
        while True:
            gates_to_evaluate = []
            for gate in gates:
                out, op, ins, delay = gate
                for s in ins:
                    if s in changed_in_round:
                        gates_to_evaluate.append(gate)
                        break

            new_assignments = []
            for gate in gates_to_evaluate:
                out, op, ins, delay = gate
                # Remove any existing pending assignment
                if out in pending_assignments:
                    del pending_assignments[out]

                # Compute new value
                in_vals = [current_values[s] for s in ins]
                if op == 'AND':
                    new_val = 1
                    for v in in_vals:
