                elif op == 'OR':
                    new_val = 0
                    for v in in_vals:
                        new_val |= v
                elif op == 'XOR':
                    new_val = sum(in_vals) % 2
                elif op == 'NAND':
                    new_val = 1
                    for v in in_vals:
