                    new_val = 1 - new_val
                elif op == 'NOR':
                    new_val = 0
                    for v in in_vals:
                        new_val |= v
                    new_val = 1 - new_val
                elif op == 'NOT':
                    new_val = 1 - in_vals[0]
                elif op == 'BUF':
                    new_val = in_vals[0]
                else:
                    raise ValueError("Invalid operation")

                if new_val != current_values[out]:
                    new_due = current_time + delay
                    if new_due <= until:
                        process_assignment(out, new_due, new_val)
