                if due_t == t:
                    current_values[sig] = val
                    changed_current.add(sig)
                else:
                    pending_assignments[sig] = (due_t, val)
            # Check if any assignments due at t now
            has_more = any(due_t == t for sig, due_t, val in new_assigns)
            if not has_more:
                break
            changed_prev = changed_current.copy()
        # Update trace
        for name in watch:
            current_val = current_values[name]
            if current_val != prev_values[name]:
                trace[name].append((t, current_val))
                prev_values[name] = current_val
        # Schedule next events from pending_assignments
        for sig in list(pending_assignments.keys()):
            due_t, val = pending_assignments[sig]
            if due_t not in seen_times and due_t <= until:
                heapq.heappush(events, due_t)
                seen_times.add(due_t)

    return trace

import heapq
from collections import defaultdict

def gate_trace(gates, stimuli, watch, until):
    # Validate gates and collect all signals
    outputs = set()
    inputs_used = set()
    gate_list = []
    for g in gates:
        out, op, ins, delay = g
        if out in outputs:
            raise ValueError("Duplicate output signal")
        outputs.add(out)
        ins_tuple = tuple(ins)
        for i in ins_tuple:
            inputs_used.add(i)
        gate_list.append((out, op, ins_tuple, delay))

    # Check for cycles using BFS to find cycles in the graph
    graph = defaultdict(list)
    for out, op, ins, delay in gate_list:
        for i in ins:
            graph[i].append(out)

    all_signals = outputs.union(inputs_used)

    # Check for cycles using Kahn's algorithm (topological sort)
    in_degree = defaultdict(int)
    for node in all_signals:
        in_degree[node] = 0
    for node in graph:
        for neighbor in graph[node]:
            in_degree[neighbor] += 1

    queue = []
    for node in all_signals:
        if in_degree[node] == 0:
            queue.append(node)

    processed = 0
    while queue:
        u = queue.pop(0)
        processed += 1
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if processed != len(all_signals):
        raise ValueError("Cycle detected")

    # Check primary inputs and stimuli
    primary_inputs = inputs_used - outputs
    for t, sig, val in stimuli:
        if sig not in primary_inputs:
            raise ValueError("Stimulus on non-primary input")

    # Check watch names
    for name in watch:
        if name not in all_signals:
            raise ValueError("Watch on unknown signal")

    # Check gate inputs are known
    for out, op, ins, delay in gate_list:
        for i in ins:
            if i not in all_signals:
                raise ValueError("Unknown signal in gate inputs")

    # Check gate operations
    valid_ops = {"AND", "OR", "XOR", "NAND", "NOR", "NOT", "BUF"}
    for out, op, ins, delay in gate_list:
        if op not in valid_ops:
            raise ValueError("Invalid gate operation")
        if op in ("NOT", "BUF") and len(ins) != 1:
            raise ValueError("Invalid input count for NOT/BUF")
        if op not in ("NOT", "BUF") and not (2 <= len(ins) <= 4):
            raise ValueError("Invalid input count for other gates")

    # Prepare current values
    current_values = {sig: 0 for sig in all_signals}

    # Prepare pending_assignments: {signal: (time, value)}
    pending_assignments = {}

    # Prepare stimuli dictionary: {time: list of (signal, value)}
    stim_dict = defaultdict(list)
    for t, sig, val in stimuli:
        stim_dict[t].append((sig, val))

    # Prepare event queue (heap)
    events = []
    seen_times = set()
    for t in stim_dict.keys():
        if t <= until and t not in seen_times:
            heapq.heappush(events, t)
            seen_times.add(t)
    heapq.heappush(events, 0)

    # Prepare trace
    trace = {name: [] for name in set(watch)}
    prev_values = {name: 0 for name in watch}

    # Process events in order
    while events:
        t = heapq.heappop(events)
        if t > until:
            continue
        # Process instant t
        # Batch round
        changed = set()
        # Apply stimuli
        for sig, val in stim_dict.get(t, []):
            prev_val = current_values[sig]
            current_values[sig] = val
            if prev_val != val:
                changed.add(sig)
        # Apply pending assignments due at t
        to_remove = []
        for sig in list(pending_assignments.keys()):
            due_time, val = pending_assignments[sig]
            if due_time == t:
                prev_val = current_values[sig]
                current_values[sig] = val
                if prev_val != val:
                    changed.add(sig)
                to_remove.append(sig)
        for sig in to_remove:
            del pending_assignments[sig]
        # Evaluate gates in rounds
        changed_prev = changed.copy()
        first_round = True
        while True:
            gates_to_eval = set()
            if first_round and t == 0:
                gates_to_eval = set(gate_list)
                first_round = False
            else:
                for g in gate_list:
                    out, op, ins, delay = g
                    for i in ins:
                        if i in changed_prev:
                            gates_to_eval.add(g)
                            break
            new_assigns = []
            changed_current = set()
            for g in gates_to_eval:
                out, op, ins, delay = g
                in_vals = [current_values[i] for i in ins]
                if op == "AND":
                    new_val = in_vals[0] & in_vals[1]
                elif op == "OR":
                    new_val = in_vals[0] | in_vals[1]
                elif op == "XOR":
                    new_val = in_vals[0] ^ in_vals[1]
                elif op == "NAND":
                    new_val = 1 - (in_vals[0] & in_vals[1])
                elif op == "NOR":
                    new_val = 1 - (in_vals[0] | in_vals[1])
                elif op == "NOT":
                    new_val = 1 - in_vals[0]
                elif op == "BUF":
                    new_val = in_vals[0]
                else:
                    assert False, "Invalid operation"
                curr_val = current_values[out]
                if new_val != curr_val:
                    due_time = t + delay
                    if due_time > until:
                        continue
                    if out in pending_assignments:
                        del pending_assignments[out]
                    new_assigns.append((out, due_time, new_val))
                    if due_time == t:
                        changed_current.add(out)
            # Apply new_assigns due at t
            for sig, due_t, val in new_assigns:
                if due_t == t:
                    current_values[sig] = val
                    changed_current.add(sig)
                else:
                    pending_assignments[sig] = (due_t, val)
            # Check if any assignments due at t
            has_more = any(due_t == t for sig, due_t, val in new_assigns)
            if not has_more:
                break
            changed_prev = changed_current.copy()
        # Update trace
        for name in watch:
            current_val = current_values[name]
            if current_val != prev_values[name]:
                trace[name].append((t, current_val))
                prev_values[name] = current_val
        # Schedule next events from pending_assignments
        for sig in list(pending_assignments.keys()):
            due_t, val = pending_assignments[sig]
            if due_t not in seen_times and due_t <= until:
                heapq.heappush(events, due_t)
                seen_times.add(due_t)

    return trace

class Type:
    def __init__(self):
        pass

class TVar(Type):
    def __init__(self, id):
        self.id = id
        super().__init__()

    def free_vars(self):
        return {self.id}

    def __str__(self):
        return f"t{self.id + 1}"

class TInt(Type):
    def __str__(self):
        return "Int"

class TBool(Type):
    def __str__(self):
        return "Bool"

class TStr(Type):
    def __str__(self):
        return "Str"

class TUnit(Type):
    def __str__(self):
        return "Unit"

class TList(Type):
    def __init__(self, elem):
        self.elem = elem

    def __str__(self):
        return f"List<{self.elem}>"

class TRef(Type):
    def __init__(self, elem):
        self.elem = elem

    def __str__(self):
        return f"Ref<{self.elem}>"

class TArrow(Type):
    def __init__(self, args, ret):
        self.args = args
        self.ret = ret

    def __str__(self):
        if len(self.args) == 1:
            return f"({self.args[0]}) -> {self.ret}"
        else:
            return f"({', '.join(map(str, self.args))}) -> {self.ret}"

def is_malformed(term):
    if not isinstance(term, tuple) or len(term) < 1:
        return True
    tag = term[0]
    if not isinstance(tag, str):
        return True
    if tag == "int":
        return len(term) != 2 or not isinstance(term[1], int)
    elif tag == "bool":
        return len(term) != 2 or not isinstance(term[1], bool)
    elif tag == "str":
        return len(term) != 2 or not isinstance(term[1], str)
    elif tag == "unit":
        return len(term) != 1
    elif tag == "var":
        return len(term) != 2 or not isinstance(term[1], str)
    elif tag == "fn":
        if len(term) != 3 or not isinstance(term[1], tuple) or len(term[1]) == 0:
            return True
        params = term[1]
        if any(not isinstance(p, str) for p in params):
            return True
        if len(set(params)) != len(params):
            return True
        return False
    elif tag == "call":
        if len(term) != 3 or not isinstance(term[1], tuple) or not isinstance(term[2], tuple):
            return True
        if len(term[2]) == 0:
            return True
        return False
    elif tag == "let":
        if len(term) != 4 or not isinstance(term[1], str) or not isinstance(term[2], tuple) or not isinstance(term[3], tuple):
            return True
        return False
    elif tag == "letrec":
        if len(term) != 4 or not isinstance(term[1], str) or not isinstance(term[2], tuple) or not isinstance(term[3], tuple):
            return True
        return False
    elif tag == "nil":
        return len(term) != 1
    elif tag == "cons":
        return len(term) != 3
    elif tag == "match":
        return len(term) != 6
    elif tag == "ref":
        return len(term) != 2
    elif tag == "get":
        return len(term) != 2
    elif tag == "set":
        return len(term) != 3
    else:
        return True

def apply_subst(t, subst):
    if isinstance(t, TVar):
        if t.id in subst:
            return apply_subst(subst[t.id], subst)
        return t
    elif isinstance(t, TList):
        return TList(apply_subst(t.elem, subst))
    elif isinstance(t, TRef):
        return TRef(apply_subst(t.elem, subst))
    elif isinstance(t, TArrow):
        return TArrow([apply_subst(a, subst) for a in t.args], apply_subst(t.ret, subst))
    return t

def occurs(var_id, t, subst):
    t = apply_subst(t, subst)
    if isinstance(t, TVar):
        return t.id == var_id
    elif isinstance(t, TList):
        return occurs(var_id, t.elem, subst)
    elif isinstance(t, TRef):
        return occurs(var_id, t.elem, subst)
    elif isinstance(t, TArrow):
        return any(occurs(var_id, a, subst) for a in t.args) or occurs(var_id, t.ret, subst)
    return False

def unify(t1, t2, subst):
    t1 = apply_subst(t1, subst)
    t2 = apply_subst(t2, subst)
    if isinstance(t1, TVar):
        if t1.id in subst:
            return unify(subst[t1.id], t2, subst)
        else:
            if occurs(t1.id, t2, subst):
                raise ValueError("Infinite type")
            new_subst = subst.copy()
            new_subst[t1.id] = t2
            return new_subst
    elif isinstance(t2, TVar):
        return unify(t2, t1, subst)
    elif isinstance(t1, TInt) and isinstance(t2, TInt):
        return subst
    elif isinstance(t1, TBool) and isinstance(t2, TBool):
        return subst
    elif isinstance(t1, TStr) and isinstance(t2, TStr):
        return subst
    elif isinstance(t1, TUnit) and isinstance(t2, TUnit):
        return subst
    elif isinstance(t1, TList) and isinstance(t2, TList):
        new_subst = unify(t1.elem, t2.elem, subst)
        return new_subst
    elif isinstance(t1, TRef) and isinstance(t2, TRef):
        new_subst = unify(t1.elem, t2.elem, subst)
        return new_subst
    elif isinstance(t1, TArrow) and isinstance(t2, TArrow):
        if len(t1.args) != len(t2.args):
            raise ValueError("Arity mismatch")
        new_subst = subst
        for a, b in zip(t1.args, t2.args):
            new_subst = unify(a, b, new_subst)
        return unify(t1.ret, t2.ret, new_subst)
    else:
        raise ValueError("Type mismatch")

def is_value(term):
    if term[0] in ("int", "bool", "str", "unit", "var", "nil"):
        return True
    elif term[0] == "fn":
        return is_value(term[2])
    elif term[0] == "cons":
        return is_value(term[1]) and is_value(term[2])
    return False

def infer(term, env, subst, next_var, vars_order):
    tag = term[0]
    if tag == "int":
        return TInt(), subst, next_var
    elif tag == "bool":
        return TBool(), subst, next_var
    elif tag == "str":
        return TStr(), subst, next_var
    elif tag == "unit":
        return TUnit(), subst, next_var
    elif tag == "var":
        name = term[1]
        for n, t in reversed(env):
            if n == name:
                return apply_subst(t, subst), subst, next_var
        raise ValueError("Unbound variable")
    elif tag == "fn":
        params = term[1]
        body = term[2]
        param_types = []
        for _ in params:
            v = TVar(next_var)
            param_types.append(v)
            vars_order.append(next_var)
            next_var +=1
        new_env = [(p, t) for p, t in zip(params, param_types)]
        new_env = env + new_env
        body_type, subst, next_var = infer(body, new_env, subst, next_var, vars_order)
        return TArrow(param_types, body_type), subst, next_var
    elif tag == "call":
        f = term[1]
        args = term[2]
        f_type, subst, next_var = infer(f, env, subst, next_var, vars_order)
        arg_types = []
        for arg in args:
            t, subst, next_var = infer(arg, env, subst, next_var, vars_order)
            arg_types.append(t)
        f_type = apply_subst(f_type, subst)
        if not isinstance(f_type, TArrow):
            raise ValueError("Not a function")
        if len(arg_types) != len(f_type.args):
            raise ValueError("Arity mismatch")
        for a, b in zip(arg_types, f_type.args):
            subst = unify(a, b, subst)
        return apply_subst(f_type.ret, subst), subst, next_var
    elif tag == "let":
        name = term[1]
        e1 = term[2]
        e2 = term[3]
        t1, subst, next_var = infer(e1, env, subst, next_var, vars_order)
        if is_value(e1):
            free = t1.free_vars()
            env_free = set()
            for _, t in env:
                env_free.update(t.free_vars())
            quantified = free - env_free
            generalized = t1
            for v in quantified:
                for t in env:
                    if isinstance(t[1], TVar) and t[1].id == v:
                        pass
            new_env = [(name, t1)]
        else:
            new_env = [(name, t1)]
        return infer(e2, new_env + env, subst, next_var, vars_order)
    elif tag == "letrec":
        name = term[1]
        e1 = term[2]
        e2 = term[3]
        if e1[0] != "fn":
            raise ValueError("letrec requires e1 to be a function")
        params = e1[1]
        param_types = []
        for _ in params:
            v = TVar(next_var)
            param_types.append(v)
            vars_order.append(next_var)
            next_var +=1
        new_env = [(name, TArrow(param_types, TVar(next_var)))]
        vars_order.append(next_var)
        next_var +=1
        body = e1[2]
        body_type, subst, next_var = infer(body, new_env + env, subst, next_var, vars_order)
        func_type = TArrow(param_types, body_type)
        subst = unify(func_type, TArrow(param_types, TVar(next_var -1)), subst)
        free = func_type.free_vars()
        env_free = set()
        for _, t in env:
            env_free.update(t.free_vars())
        quantified = free - env_free
        generalized = func_type
        new_env = [(name, func_type)]
        return infer(e2, new_env + env, subst, next_var, vars_order)
    elif tag == "nil":
        v = TVar(next_var)
        vars_order.append(next_var)
        next_var +=1
        return TList(v), subst, next_var
    elif tag == "cons":
        h = term[1]
        t = term[2]
        h_type, subst, next_var = infer(h, env, subst, next_var, vars_order)
        t_type, subst, next_var = infer(t, env, subst, next_var, vars_order)
        t_type = apply_subst(t_type, subst)
        if not isinstance(t_type, TList):
            raise ValueError("cons requires second argument to be list")
        subst = unify(h_type, t_type.elem, subst)
        return TList(apply_subst(t_type.elem, subst)), subst, next_var
    elif tag == "match":
        s = term[1]
        e_nil = term[2]
        hn = term[3]
        tn = term[4]
        e_cons = term[5]
        s_type, subst, next_var = infer(s, env, subst, next_var, vars_order)
        s_type = apply_subst(s_type, subst)
        if not isinstance(s_type, TList):
            raise ValueError("match requires list")
        a_type = s_type.elem
        new_env = env + [(hn, a_type), (tn, s_type)]
        t_nil, subst, next_var = infer(e_nil, new_env, subst, next_var, vars_order)
        new_env = env + [(hn, a_type), (tn, s_type)]
        t_cons, subst, next_var = infer(e_cons, new_env, subst, next_var, vars_order)
        subst = unify(t_nil, t_cons, subst)
        return apply_subst(t_nil, subst), subst, next_var
    elif tag == "ref":
        e = term[1]
        e_type, subst, next_var = infer(e, env, subst, next_var, vars_order)
        return TRef(e_type), subst, next_var
    elif tag == "get":
        r = term[1]
        r_type, subst, next_var = infer(r, env, subst, next_var, vars_order)
        r_type = apply_subst(r_type, subst)
        if not isinstance(r_type, TRef):
            raise ValueError("get requires reference")
        return r_type.elem, subst, next_var
    elif tag == "set":
        r = term[1]
        e = term[2]
        r_type, subst, next_var = infer(r, env, subst, next_var, vars_order)
        e_type, subst, next_var = infer(e, env, subst, next_var, vars_order)
        r_type = apply_subst(r_type, subst)
        if not isinstance(r_type, TRef):
            raise ValueError("set requires reference")
        subst = unify(e_type, r_type.elem, subst)
        return TUnit(), subst, next_var
    else:
        raise ValueError("Unknown tag")

def weak_infer(term):
    if is_malformed(term):
        raise ValueError("Malformed term")
    env = [
        ("plus", TArrow([TInt(), TInt()], TInt())),
        ("eq", TArrow([TVar(0), TVar(0)], TBool())),
        ("size", TArrow([TStr()], TInt()))
    ]
    next_var = 1
    vars_order = []
    subst = {}
    t, subst, next_var = infer(term, env, subst, next_var, vars_order)
    t = apply_subst(t, subst)
    for v in vars_order:
        t = t.substitute(TVar(v), TVar(vars_order.index(v)))
    return str(t)

import sys
from typing import Dict, List, Tuple, Any, Optional

class Type:
    def __init__(self):
        pass

    def __repr__(self):
        return self.__str__()

    def free_vars(self) -> set:
        return set()

    def substitute(self, subst: Dict[str, 'Type']) -> 'Type':
        return self

class TVar(Type):
    count = 0

    def __init__(self, name=None):
        if name is None:
            TVar.count += 1
            self.name = f"t{TVar.count}"
        else:
            self.name = name

    def __str__(self):
        return self.name

    def free_vars(self):
        return {self.name}

    def substitute(self, subst):
        if self.name in subst:
            return subst[self.name].substitute(subst)
        return self

class TInt(Type):
    def __str__(self):
        return "Int"

class TBool(Type):
    def __str__(self):
        return "Bool"

class TStr(Type):
    def __str__(self):
        return "Str"

class TUnit(Type):
    def __str__(self):
        return "Unit"

class TList(Type):
    def __init__(self, elem: Type):
        self.elem = elem

    def __str__(self):
        return f"List<{self.elem}>"

    def free_vars(self):
        return self.elem.free_vars()

    def substitute(self, subst):
        return TList(self.elem.substitute(subst))

class TRef(Type):
    def __init__(self, elem: Type):
        self.elem = elem

    def __str__(self):
        return f"Ref<{self.elem}>"

    def free_vars(self):
        return self.elem.free_vars()

    def substitute(self, subst):
        return TRef(self.elem.substitute(subst))

class TFunc(Type):
    def __init__(self, params: Tuple[Type, ...], ret: Type):
        self.params = params
        self.ret = ret

    def __str__(self):
        if len(self.params) == 1:
            p_str = str(self.params[0])
            if isinstance(self.params[0], TFunc):
                p_str = f"({p_str})"
            return f"{p_str} -> {self.ret}"
        else:
            params_str = ", ".join(str(p) for p in self.params)
            return f"({params_str}) -> {self.ret}"

    def free_vars(self):
        return set().union(*[p.free_vars() for p in self.params], self.ret.free_vars())

    def substitute(self, subst):
        new_params = tuple(p.substitute(subst) for p in self.params)
        new_ret = self.ret.substitute(subst)
        return TFunc(new_params, new_ret)

def fresh_var() -> TVar:
    return TVar()

def validate_term(term):
    if not isinstance(term, tuple):
        raise ValueError("Term is not a tuple")
    if len(term) == 0:
        raise ValueError("Empty tuple")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Tag is not a string")
    valid_tags = ["int", "bool", "str", "unit", "var", "fn", "call", "let", "letrec", "nil", "cons", "match", "ref", "get", "set"]
    if tag not in valid_tags:
        raise ValueError(f"Unknown tag: {tag}")
    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int):
            raise ValueError("Invalid int term")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Invalid bool term")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str):
            raise ValueError("Invalid str term")
    elif tag == "unit":
        if len(term) != 1:
            raise ValueError("Invalid unit term")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Invalid var term")
    elif tag == "fn":
        if len(term) != 3:
            raise ValueError("Invalid fn term")
        params = term[1]
        if not isinstance(params, tuple) or len(params) == 0:
            raise ValueError("Fn params must be non-empty tuple")
        for p in params:
            if not isinstance(p, str) or not p:
                raise ValueError("Invalid fn param")
        if len(set(params)) != len(params):
            raise ValueError("Fn params must be distinct")
        body = term[2]
        validate_term(body)
    elif tag == "call":
        if len(term) != 3:
            raise ValueError("Invalid call term")
        f = term[1]
        args = term[2]
        if not isinstance(args, tuple) or len(args) == 0:
            raise ValueError("Call args must be non-empty tuple")
        validate_term(f)
        for arg in args:
            validate_term(arg)
    elif tag == "let":
        if len(term) != 4:
            raise ValueError("Invalid let term")
        name = term[1]
        if not isinstance(name, str) or not name:
            raise ValueError("Invalid let name")
        e1 = term[2]
        e2 = term[3]
        validate_term(e1)
        validate_term(e2)
    elif tag == "letrec":
        if len(term) != 4:
            raise ValueError("Invalid letrec term")
        name = term[1]
        if not isinstance(name, str) or not name:
            raise ValueError("Invalid letrec name")
        e1 = term[2]
        e2 = term[3]
        validate_term(e1)
        validate_term(e2)
    elif tag == "nil":
        if len(term) != 1:
            raise ValueError("Invalid nil term")
    elif tag == "cons":
        if len(term) != 3:
            raise ValueError("Invalid cons term")
        h = term[1]
        t = term[2]
        validate_term(h)
        validate_term(t)
    elif tag == "match":
        if len(term) != 6:
            raise ValueError("Invalid match term")
        s = term[1]
        e_nil = term[2]
        hn = term[3]
        tn = term[4]
        e_cons = term[5]
        if not isinstance(hn, str) or not hn or not isinstance(tn, str) or not tn or hn == tn:
            raise ValueError("Invalid match bindings")
        validate_term(s)
        validate_term(e_nil)
        validate_term(e_cons)
    elif tag == "ref":
        if len(term) != 2:
            raise ValueError("Invalid ref term")
        e = term[1]
        validate_term(e)
    elif tag == "get":
        if len(term) != 2:
            raise ValueError("Invalid get term")
        r = term[1]
        validate_term(r)
    elif tag == "set":
        if len(term) != 3:
            raise ValueError("Invalid set term")
        r = term[1]
        e = term[2]
        validate_term(r)
        validate_term(e)

def weak_infer(term) -> str:
    validate_term(term)
    env = {
        'plus': TFunc((TInt, TInt), TInt),
        'eq': TFunc((TVar(), TVar()), TBool),
        'size': TFunc((TStr,), TInt)
    }
    subst = {}
    type_var_counter = [0]

    def new_var():
        type_var_counter[0] += 1
        return TVar(f"t{type_var_counter[0]}")

    def free_vars_in_env():
        s = set()
        for t in env.values():
            s.update(t.free_vars())
        return s

    def infer(term, env):
        if term[0] == "int":
            return TInt()
        elif term[0] == "bool":
            return TBool()
        elif term[0] == "str":
            return TStr()
        elif term[0] == "unit":
            return TUnit()
        elif term[0] == "var":
            name = term[1]
            if name not in env:
                raise ValueError(f"Unbound variable: {name}")
            return env[name]
        elif term[0] == "fn":
            params = term[1]
            body = term[2]
            param_types = tuple(new_var() for _ in params)
            new_env = dict(env)
            for p, t in zip(params, param_types):
                new_env[p] = t
            body_type = infer(body, new_env)
            return TFunc(param_types, body_type)
        elif term[0] == "call":
            f = term[1]
            args = term[2]
            f_type = infer(f, env)
            if not isinstance(f_type, TFunc):
                raise ValueError("Called non-function")
            if len(args) != len(f_type.params):
                raise ValueError("Arity mismatch")
            arg_types = [infer(arg, env) for arg in args]
            for arg_t, param_t in zip(arg_types, f_type.params):
                unify(arg_t, param_t)
            return f_type.ret
        elif term[0] == "let":
            name = term[1]
            e1 = term[2]
            e2 = term[3]
            e1_type = infer(e1, env)
            if is_value(e1):
                generalized = generalize(e1_type)
                new_env = dict(env)
                new_env[name] = generalized
            else:
                new_env = dict(env)
                new_env[name] = e1_type
            return infer(e2, new_env)
        elif term[0] == "letrec":
            name = term[1]
            e1 = term[2]
            e2 = term[3]
            if e1[0] != "fn":
                raise ValueError("letrec requires fn term")
            name_type = new_var()
            new_env = dict(env)
            new_env[name] = name_type
            e1_type = infer(e1, new_env)
            unify(name_type, e1_type)
            generalized = generalize(e1_type)
            new_env[name] = generalized
            return infer(e2, new_env)
        elif term[0] == "nil":
            return TList(new_var())
        elif term[0] == "cons":
            h = term[1]
            t = term[2]
            h_type = infer(h, env)
            t_type = infer(t, env)
            unify(t_type, TList(h_type))
            return TList(h_type)
        elif term[0] == "match":
            s = term[1]
            e_nil = term[2]
            hn = term[3]
            tn = term[4]
            e_cons = term[5]
            s_type = infer(s, env)
            if not isinstance(s_type, TList):
                raise ValueError("Match on non-list")
            elem_type = s_type.elem
            e_nil_type = infer(e_nil, env)
            hn_type = elem_type
            tn_type = TList(elem_type)
            new_env = dict(env)
            new_env[hn] = hn_type
            new_env[tn] = tn_type
            e_cons_type = infer(e_cons, new_env)
            unify(e_nil_type, e_cons_type)
            return e_nil_type
        elif term[0] == "ref":
            e = term[1]
            e_type = infer(e, env)
            return TRef(e_type)
        elif term[0] == "get":
            r = term[1]
            r_type = infer(r, env)
            if not isinstance(r_type, TRef):
                raise ValueError("Get on non-ref")
            return r_type.elem
        elif term[0] == "set":
            r = term[1]
            e = term[2]
            r_type = infer(r, env)
            if not isinstance(r_type, TRef):
                raise ValueError("Set on non-ref")
            e_type = infer(e, env)
            unify(e_type, r_type.elem)
            return TUnit()
        else:
            raise ValueError("Unknown term")

    def unify(t1: Type, t2: Type):
        t1 = t1.substitute(subst)
        t2 = t2.substitute(subst)
        if isinstance(t1, TVar) and isinstance(t2, TVar):
            if t1.name == t2.name:
                return
            subst[t1.name] = t2
        elif isinstance(t1, TVar):
            subst[t1.name] = t2
        elif isinstance(t2, TVar):
            subst[t2.name] = t1
        elif isinstance(t1, TFunc) and isinstance(t2, TFunc):
            if len(t1.params) != len(t2.params):
                raise ValueError("Arity mismatch in unify")
            for a, b in zip(t1.params, t2.params):
                unify(a, b)
            unify(t1.ret, t2.ret)
        elif isinstance(t1, TList) and isinstance(t2, TList):
            unify(t1.elem, t2.elem)
        elif isinstance(t1, TRef) and isinstance(t2, TRef):
            unify(t1.elem, t2.elem)
        elif type(t1) != type(t2):
            raise ValueError("Type mismatch")
        else:
            if t1 != t2:
                raise ValueError("Type mismatch")

    def generalize(t: Type) -> Type:
        free = t.free_vars()
        env_free = free_vars_in_env()
        quantified = free - env_free
        return t

    def is_value(term):
        if term[0] in ("int", "bool", "str", "unit", "var", "fn", "nil"):
            return True
        if term[0] == "cons":
            return is_value(term[1]) and is_value(term[2])
        return False

    result_type = infer(term, env)
    result_type = result_type.substitute(subst)
    return str(result_type)

from collections import defaultdict

class Type:
    def __init__(self):
        self.vars = []
        self.var_count = 0

    def fresh_var(self):
        self.var_count += 1
        var = f't{self.var_count}'
        self.vars.append(var)
        return var

    def get_vars(self, t):
        if isinstance(t, str):
            return set() if t in ("Int", "Bool", "Str", "Unit") else {t}
        elif isinstance(t, tuple):
            if t[0] == '->':
                return self.get_vars(t[1]) | self.get_vars(t[2])
            elif t[0] == 'List':
                return self.get_vars(t[1])
            elif t[0] == 'Ref':
                return self.get_vars(t[1])
            else:
                return set()
        else:
            return set()

    def substitute(self, t, subst):
        if isinstance(t, str):
            if t in subst:
                return self.substitute(subst[t], subst)
            return t
        elif isinstance(t, tuple):
            if t[0] == '->':
                return ('->', self.substitute(t[1], subst), self.substitute(t[2], subst))
            elif t[0] == 'List':
                return ('List', self.substitute(t[1], subst))
            elif t[0] == 'Ref':
                return ('Ref', self.substitute(t[1], subst))
            else:
                return t
        else:
            return t

    def unify(self, t1, t2, subst):
        t1 = self.substitute(t1, subst)
        t2 = self.substitute(t2, subst)
        if t1 == t2:
            return subst
        if isinstance(t1, str) and t1[0] == 't':
            if t1 in t2:
                return None
            new_subst = dict(subst)
            new_subst[t1] = t2
            return new_subst
        if isinstance(t2, str) and t2[0] == 't':
            if t2 in t1:
                return None
            new_subst = dict(subst)
            new_subst[t2] = t1
            return new_subst
        if isinstance(t1, tuple) and isinstance(t2, tuple):
            if t1[0] != t2[0]:
                return None
            if t1[0] == '->':
                subst = self.unify(t1[1], t2[1], subst)
                if subst is None:
                    return None
                return self.unify(t1[2], t2[2], subst)
            elif t1[0] == 'List':
                return self.unify(t1[1], t2[1], subst)
            elif t1[0] == 'Ref':
                return self.unify(t1[1], t2[1], subst)
        return None

def is_value(term):
    if term[0] in ("int", "bool", "str", "unit"):
        return True
    elif term[0] == "var":
        return True
    elif term[0] == "fn":
        return True
    elif term[0] == "nil":
        return True
    elif term[0] == "cons":
        return is_value(term[1]) and is_value(term[2])
    return False

def validate_term(term):
    if not isinstance(term, tuple):
        raise ValueError("Term is not a tuple")
    if len(term) == 0:
        raise ValueError("Empty term")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Tag is not a string")
    valid_tags = ["int", "bool", "str", "unit", "var", "fn", "call", "let", "letrec", "nil", "cons", "match", "ref", "get", "set"]
    if tag not in valid_tags:
        raise ValueError("Unknown tag")
    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int):
            raise ValueError("Invalid int term")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Invalid bool term")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str):
            raise ValueError("Invalid str term")
    elif tag == "unit":
        if len(term) != 1:
            raise ValueError("Invalid unit term")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or len(term[1]) == 0:
            raise ValueError("Invalid var term")
    elif tag == "fn":
        if len(term) != 3 or not isinstance(term[1], tuple) or len(term[1]) == 0:
            raise ValueError("Invalid fn term")
        params = term[1]
        seen = set()
        for p in params:
            if not isinstance(p, str) or len(p) == 0 or p in seen:
                raise ValueError("Invalid fn params")
            seen.add(p)
        validate_term(term[2])
    elif tag == "call":
        if len(term) != 3 or not isinstance(term[2], tuple) or len(term[2]) == 0:
            raise ValueError("Invalid call term")
        validate_term(term[1])
        for a in term[2]:
            validate_term(a)
    elif tag == "let":
        if len(term) != 4 or not isinstance(term[1], str) or len(term[1]) == 0:
            raise ValueError("Invalid let term")
        validate_term(term[2])
        validate_term(term[3])
    elif tag == "letrec":
        if len(term) != 4 or not isinstance(term[1], str) or len(term[1]) == 0:
            raise ValueError("Invalid letrec term")
        if term[2][0] != "fn":
            raise ValueError("letrec e1 must be a fn term")
        validate_term(term[2])
        validate_term(term[3])
    elif tag == "nil":
        if len(term) != 1:
            raise ValueError("Invalid nil term")
    elif tag == "cons":
        if len(term) != 3:
            raise ValueError("Invalid cons term")
        validate_term(term[1])
        validate_term(term[2])
    elif tag == "match":
        if len(term) != 6:
            raise ValueError("Invalid match term")
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if not (isinstance(hn, str) and len(hn) > 0 and isinstance(tn, str) and len(tn) > 0 and hn != tn):
            raise ValueError("Invalid match names")
        validate_term(s)
        validate_term(e_nil)
        validate_term(e_cons)
    elif tag == "ref":
        if len(term) != 2:
            raise ValueError("Invalid ref term")
        validate_term(term[1])
    elif tag == "get":
        if len(term) != 2:
            raise ValueError("Invalid get term")
        validate_term(term[1])
    elif tag == "set":
        if len(term) != 3:
            raise ValueError("Invalid set term")
        validate_term(term[1])
        validate_term(term[2])

def weak_infer(term):
    validate_term(term)
    type_inf = Type()
    env = {
        'plus': (('->', ('Int', 'Int'), 'Int'), []),
        'eq': (('->', (('a', 'a'), 'Bool'), []), ['a']),
        'size': (('->', 'Str', 'Int'), []),
    }

    def infer(term, env, subst):
        if term[0] in ("int", "bool", "str", "unit"):
            base = {"int": "Int", "bool": "Bool", "str": "Str", "unit": "Unit"}
            return base[term[0]], subst
        elif term[0] == "var":
            name = term[1]
            if name not in env:
                raise ValueError(f"Unbound variable {name}")
            t, qs = env[name]
            # Instantiate type scheme
            fresh_vars = {}
            for q in qs:
                fresh_vars[q] = type_inf.fresh_var()
            new_t = type_inf.substitute(t, fresh_vars)
            return type_inf.substitute(new_t, subst), subst
        elif term[0] == "fn":
            params = term[1]
            body = term[2]
            param_types = [type_inf.fresh_var() for _ in params]
            new_env = dict(env)
            for p, pt in zip(params, param_types):
                new_env[p] = (pt, [])
            body_t, subst = infer(body, new_env, subst)
            for pt in param_types:
                body_t, subst = type_inf.unify(body_t, subst.get(pt, pt), subst)
            func_type = (tuple(param_types), body_t)
            return func_type, subst
        elif term[0] == "call":
            f = term[1]
            args = term[2]
            f_t, subst = infer(f, env, subst)
            arg_types = []
            for a in args:
                a_t, subst = infer(a, env, subst)
                arg_types.append(a_t)
            func_type, subst = type_inf.unify(f_t, (tuple(arg_types), type_inf.fresh_var()), subst)
            if func_type is None:
                raise ValueError("Type mismatch in call")
            return func_type[1], subst
        elif term[0] == "let":
            name = term[1]
            e1 = term[2]
            e2 = term[3]
            e1_t, subst = infer(e1, env, subst)
            if is_value(e1):
                # Generalize
                free = set()
                for v in e1_t[0] if isinstance(e1_t, tuple) else e1_t:
                    if isinstance(v, str) and v.startswith('t'):
                        free.add(v)
                env_free = set()
                for entry in env.values():
                    t, _ = entry
                    for v in type_inf.get_vars(t):
                        env_free.add(v)
                quantified = [v for v in free if v not in env_free]
                env[name] = (e1_t, quantified)
            else:
                env[name] = (e1_t, [])
            return infer(e2, env, subst)
        elif term[0] == "letrec":
            name = term[1]
            e1 = term[2]
            e2 = term[3]
            if e1[0] != "fn":
                raise ValueError("letrec e1 must be a fn term")
            params = e1[1]
            body = e1[2]
            # Create a type variable for the function's return type
            ret_type = type_inf.fresh_var()
            param_types = [type_inf.fresh_var() for _ in params]
            func_type = (tuple(param_types), ret_type)
            env[name] = (func_type, [])
            # Infer the body with the name bound to the function's type
            body_t, subst = infer(body, env, subst)
            # Unify the inferred body type with the function's return type
            func_type, subst = type_inf.unify(func_type[1], body_t, subst)
            if func_type is None:
                raise ValueError("Type mismatch in letrec")
            # Generalize the function's type
            free = set()
            for v in func_type[0] + (func_type[1],):
                if isinstance(v, str) and v.startswith('t'):
                    free.add(v)
            env_free = set()
            for entry in env.values():
                t, _ = entry
                for v in type_inf.get_vars(t):
                    env_free.add(v)
            quantified = [v for v in free if v not in env_free]
            env[name] = (func_type, quantified)
            return infer(e2, env, subst)
        elif term[0] == "nil":
            t = type_inf.fresh_var()
            return ('List', t), subst
        elif term[0] == "cons":
            h = term[1]
            t = term[2]
            h_t, subst = infer(h, env, subst)
            t_t, subst = infer(t, env, subst)
            t_t, subst = type_inf.unify(t_t, ('List', h_t), subst)
            return ('List', h_t), subst
        elif term[0] == "match":
            s = term[1]
            e_nil = term[2]
            hn = term[3]
            tn = term[4]
            e_cons = term[5]
            s_t, subst = infer(s, env, subst)
            a_var = type_inf.fresh_var()
            s_t, subst = type_inf.unify(s_t, ('List', a_var), subst)
            if s_t is None:
                raise ValueError("Match subject must be a list")
            new_env_nil = dict(env)
            new_env_nil[hn] = (a_var, [])
            new_env_nil[tn] = (('List', a_var), [])
            e_nil_t, subst = infer(e_nil, new_env_nil, subst)
            new_env_cons = dict(env)
            new_env_cons[hn] = (a_var, [])
            new_env_cons[tn] = (('List', a_var), [])
            e_cons_t, subst = infer(e_cons, new_env_cons, subst)
            e_nil_t, subst = type_inf.unify(e_nil_t, e_cons_t, subst)
            return e_nil_t, subst
        elif term[0] == "ref":
            e = term[1]
            e_t, subst = infer(e, env, subst)
            return ('Ref', e_t), subst
        elif term[0] == "get":
            r = term[1]
            r_t, subst = infer(r, env, subst)
            r_t, subst = type_inf.unify(r_t, ('Ref', type_inf.fresh_var()), subst)
            return r_t[1], subst
        elif term[0] == "set":
            r = term[1]
            e = term[2]
            r_t, subst = infer(r, env, subst)
            e_t, subst = infer(e, env, subst)
            a_var = type_inf.fresh_var()
            r_t, subst = type_inf.unify(r_t, ('Ref', a_var), subst)
            subst = type_inf.unify(a_var, e_t, subst)
            return 'Unit', subst
        else:
            raise ValueError(f"Unknown term {term[0]}")

    try:
        inferred_type, subst = infer(term, env, {})
        # Apply substitution to the inferred type
        inferred_type = type_inf.substitute(inferred_type, subst)
        # Convert the type to a string
        def type_to_str(t, vars):
            if isinstance(t, str):
                if t.startswith('t'):
                    return t
                return t
            elif isinstance(t, tuple):
                if t[0] == '->':
                    params, ret = t[1], t[2]
                    if isinstance(params, tuple):
                        params_str = ', '.join(type_to_str(p, vars) for p in params)
                        return f"({params_str}) -> {type_to_str(ret, vars)}"
                    else:
                        return f"{type_to_str(params, vars)} -> {type_to_str(ret, vars)}"
                elif t[0] == 'List':
                    return f"List<{type_to_str(t[1], vars)}>"
                elif t[0] == 'Ref':
                    return f"Ref<{type_to_str(t[1], vars)}>"
            return str(t)
        vars = []
        def collect_vars(t):
            if isinstance(t, str) and t.startswith('t'):
                if t not in vars:
                    vars.append(t)
            elif isinstance(t, tuple):
                if t[0] == '->':
                    collect_vars(t[1])
                    collect_vars(t[2])
                elif t[0] in ('List', 'Ref'):
                    collect_vars(t[1])
        collect_vars(inferred_type)
        var_map = {v: f't{i+1}' for i, v in enumerate(vars)}
        def replace_vars(t):
            if isinstance(t, str):
                if t.startswith('t') and t in var_map:
                    return var_map[t]
                return t
            elif isinstance(t, tuple):
                if t[0] == '->':
                    return ('->', replace_vars(t[1]), replace_vars(t[2]))
                elif t[0] == 'List':
                    return ('List', replace_vars(t[1]))
                elif t[0] == 'Ref':
                    return ('Ref', replace_vars(t[1]))
            return t
        inferred_type = replace_vars(inferred_type)
        return type_to_str(inferred_type, [])
    except ValueError:
        raise ValueError("Ill-typed term")

import sys

class TypeError(ValueError):
    pass

class TypeVar:
    def __init__(self, name):
        self.name = name

    def __repr__(self):
        return self.name

    def __eq__(self, other):
        return isinstance(other, TypeVar) and self.name == other.name

    def __hash__(self):
        return hash(self.name)

    def __str__(self):
        return self.name

    def __lt__(self, other):
        if isinstance(other, TypeVar):
            return self.name < other.name
        return True

def check_term(term):
    if not isinstance(term, tuple):
        raise TypeError("Term is not a tuple")
    if len(term) == 0:
        raise TypeError("Empty tuple")
    tag = term[0]
    if not isinstance(tag, str):
        raise TypeError("Tag is not a string")
    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int):
            raise TypeError("Invalid int term")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool):
            raise TypeError("Invalid bool term")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str):
            raise TypeError("Invalid str term")
