class Type:
    pass

class TypeVar(Type):
    _id = 0
    def __init__(self):
        self.id = TypeVar._id
        TypeVar._id += 1
    def __repr__(self):
        return f"t{self.id}"

class IntT(Type):
    def __repr__(self):
        return "Int"

class BoolT(Type):
    def __repr__(self):
        return "Bool"

class StrT(Type):
    def __repr__(self):
        return "Str"

class UnitT(Type):
    def __repr__(self):
        return "Unit"

class ListT(Type):
    def __init__(self, elem):
        self.elem = elem
    def __repr__(self):
        return f"List<{self.elem}>"

class RefT(Type):
    def __init__(self, typ):
        self.typ = typ
    def __repr__(self):
        return f"Ref<{self.typ}>"

class FunctionT(Type):
    def __init__(self, params, ret):
        self.params = params
        self.ret = ret
    def __repr__(self):
        if len(self.params) == 1:
            return f"({self.params[0]}) -> {self.ret}"
        else:
            return f"({', '.join(map(str, self.params))}) -> {self.ret}"

def is_value(term):
    if not isinstance(term, tuple) or not term:
        return False
    tag = term[0]
    if tag in ("int", "bool", "str", "unit"):
        return True
    elif tag in ("var", "fn", "nil"):
        return True
    elif tag == "cons":
        h, t = term[1], term[2]
        return is_value(h) and is_value(t)
    return False

def occurs(var, typ, subst):
    typ = apply_subst(typ, subst)
    if isinstance(typ, TypeVar):
        return typ == var
    elif isinstance(typ, FunctionT):
        return any(occurs(var, p, subst) for p in typ.params) or occurs(var, typ.ret, subst)
    elif isinstance(typ, ListT):
        return occurs(var, typ.elem, subst)
    elif isinstance(typ, RefT):
