        params, body = term[1], term[2]
        if not isinstance(params, tuple) or not params:
            raise ValueError("Malformed term")
        for name in params:
            if not isinstance(name, str) or not name:
                raise ValueError("Malformed term")
        if len(set(params)) != len(params):
            raise ValueError("Malformed term")
        param_types = [TypeVar() for _ in params]
        new_env = env.copy()
        for name, typ in zip(params, param_types):
            new_env[name] = typ
        body_type = infer(body, new_env)
        return FunctionT(param_types, body_type)
    elif tag == "call":
        if len(term) != 3:
            raise ValueError("Malformed term")
        f, args = term[1], term[2]
        if not isinstance(args, tuple) or not args:
            raise ValueError("Malformed term")
        f_type = infer(f, env)
        args_types = [infer(arg, env) for arg in args]
        if not isinstance(f_type, FunctionT):
            raise ValueError("Type mismatch")
        if len(f_type.params) != len(args_types):
            raise ValueError("Arity mismatch")
        subst = {}
        for p, a in zip(f_type.params, args_types):
            subst = unify(p, a, subst)
        ret_type = apply_subst(f_type.ret, subst)
        return ret_type
    elif tag == "let":
        if len(term) != 4:
            raise ValueError("Malformed term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name:
            raise ValueError("Malformed term")
        e1_type = infer(e1, env)
        if is_value(e1):
            generalized_type = generalize(e1_type, env, {})
        else:
            generalized_type = e1_type
        new_env = env.copy()
        new_env[name] = generalized_type
        return infer(e2, new_env)
    elif tag == "letrec":
        if len(term) != 4:
            raise ValueError("Malformed term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name:
            raise ValueError("Malformed term")
        if not isinstance(e1, tuple) or e1[0] != "fn":
            raise ValueError("letrec requires e1 to be a function")
        f_type = TypeVar()
        new_env = env.copy()
        new_env[name] = f_type
        e1_type = infer(e1, new_env)
        generalized_type = generalize(e1_type, env, {})
        new_env_final = env.copy()
        new_env_final[name] = generalized_type
        return infer(e2, new_env_final)
    elif tag == "nil":
        if len(term) != 1:
            raise ValueError("Malformed term")
        return ListT(TypeVar())
    elif tag == "cons":
        if len(term) != 3:
            raise ValueError("Malformed term")
        h, t = term[1], term[2]
        h_type = infer(h, env)
        t_type = infer(t, env)
        if not isinstance(t_type, ListT):
            raise ValueError("Type mismatch")
        subst = unify(h_type, t_type.elem, {})
        return ListT(apply_subst(h_type, subst))
    elif tag == "match":
        if len(term) != 6:
            raise ValueError("Malformed term")
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if hn == tn:
            raise ValueError("hn and tn must differ")
        s_type = infer(s, env)
        if not isinstance(s_type, ListT):
            raise ValueError("Type mismatch")
        a = s_type.elem
        new_env_nil = env.copy()
        e_nil_type = infer(e_nil, new_env_nil)
        new_env_cons = env.copy()
        new_env_cons[hn] = a
        new_env_cons[tn] = s_type
        e_cons_type = infer(e_cons, new_env_cons)
        if e_nil_type != e_cons_type:
            raise ValueError("Type mismatch in branches")
        return e_nil_type
    elif tag == "ref":
        if len(term) != 2:
            raise ValueError("Malformed term")
        e = term[1]
        e_type = infer(e, env)
        return RefT(e_type)
    elif tag == "get":
        if len(term) != 2:
            raise ValueError("Malformed term")
        r = term[1]
        r_type = infer(r, env)
        if not isinstance(r_type, RefT):
            raise ValueError("Type mismatch")
        return r_type.typ
    elif tag == "set":
        if len(term) != 3:
            raise ValueError("Malformed term")
        r, e = term[1], term[2]
        r_type = infer(r, env)
        if not isinstance(r_type, RefT):
            raise ValueError("Type mismatch")
        e_type = infer(e, env)
        subst = unify(e_type, r_type.typ, {})
        return UnitT()
    else:
        raise ValueError("Unknown tag")

