def group_type(term: Any) -> str:
    if is_malformed(term):
        raise ValueError("Malformed term")

    substitution = {}
    counter = [0]
    env = {
        "add": FunT(IntT(), FunT(IntT(), IntT())),
        "eq": FunT(VarT("a"), FunT(VarT("a"), BoolT())),
        "nil": ListT(VarT("a")),
        "cons": FunT(VarT("a"), FunT(ListT(VarT("a")), ListT(VarT("a")))),
        "head": FunT(ListT(VarT("a")), VarT("a")),
        "tail": FunT(ListT(VarT("a")), ListT(VarT("a"))),
        "isnil": FunT(ListT(VarT("a")), BoolT())
    }

    def apply_subst(t: Type) -> Type:
        if isinstance(t, TypeVar):
            if t.name in substitution:
                return substitution[t.name]
            else:
                return t
        elif isinstance(t, FunT):
            return FunT(apply_subst(t.a), apply_subst(t.b))
        elif isinstance(t, ListT):
            return ListT(apply_subst(t.a))
        elif isinstance(t, TupleT):
            return TupleT([apply_subst(e) for e in t.types])
        else:
            return t

    def unify(t1: Type, t2: Type):
        t1 = apply_subst(t1)
        t2 = apply_subst(t2)
        if t1 == t2:
            return
        elif isinstance(t1, TypeVar):
            if occurs(t1, t2):
                raise ValueError("Infinite type")
            substitution[t1.name] = t2
        elif isinstance(t2, TypeVar):
            if occurs(t2, t1):
                raise ValueError("Infinite type")
            substitution[t2.name] = t1
        elif isinstance(t1, FunT) and isinstance(t2, FunT):
            unify(t1.a, t2.a)
            unify(t1.b, t2.b)
        elif isinstance(t1, ListT) and isinstance(t2, ListT):
            unify(t1.a, t2.a)
        elif isinstance(t1, TupleT) and isinstance(t2, TupleT):
            if len(t1.types) != len(t2.types):
                raise ValueError("Tuple length mismatch")
            for a, b in zip(t1.types, t2.types):
                unify(a, b)
        else:
            raise ValueError("Type mismatch")

    def occurs(tv: TypeVar, t: Type) -> bool:
        t = apply_subst(t)
        if isinstance(t, TypeVar):
            return t.name == tv.name
        elif isinstance(t, FunT):
            return occurs(tv, t.a) or occurs(tv, t.b)
        elif isinstance(t, ListT):
            return occurs(tv, t.a)
        elif isinstance(t, TupleT):
            return any(occurs(tv, e) for e in t.types)
        else:
            return False

