            elif tag == "app":
                f, a = t[1], t[2]
                f_type = gen_type(f, env)
                a_type = gen_type(a, env)
                b = fresh_var(counter)
                unify(f_type, FunT(a_type, b))
                return b
            elif tag == "if":
                c, t_branch, e = t[1], t[2], t[3]
                c_type = gen_type(c, env)
                unify(c_type, BoolT())
                t_type = gen_type(t_branch, env)
                e_type = gen_type(e, env)
                unify(t_type, e_type)
                return t_type
            elif tag == "let":
                x, e1, e2 = t[1], t[2], t[3]
                e1_type = gen_type(e1, env)
                free = free_vars(env)
                generalized = generalize(e1_type, free)
                new_env = env.copy()
                new_env[x] = generalized
                return gen_type(e2, new_env)
            elif tag == "letrec":
                group, body = t[1], t[2]
