    def free_vars(env: Dict[str, Type]) -> Set[str]:
        free = set()
        for typ in env.values():
            collect_free(typ, free)
        return free

    def collect_free(t: Type, free: Set[str]):
        if isinstance(t, TypeVar):
            if t.name not in substitution:
                free.add(t.name)
        elif isinstance(t, FunT):
            collect_free(t.a, free)
            collect_free(t.b, free)
        elif isinstance(t, ListT):
