                else:
                    new_var = fresh_var(counter)
                    var_map[t.name] = new_var
                    return new_var
            elif isinstance(t, FunT):
                return FunT(fresh_map(t.a), fresh_map(t.b))
            elif isinstance(t, ListT):
                return ListT(fresh_map(t.a))
            elif isinstance(t, TupleT):
                return TupleT([fresh_map(e) for e in t.types])
            else:
                return t
        return fresh_map(t)

    try:
        typ = gen_type(term, env)
        typ = apply_subst(typ)
        return str(typ)
