        def __eq__(self, other):
            return isinstance(other, TTuple) and self.elements == other.elements

        def __hash__(self):
            return hash(self.elements)

        def __repr__(self):
            if not self.elements:
                return "()"
            return "(" + " ".join(repr(e) for e in self.elements) + ")"

    class TInt(Type):
        def __eq__(self, other):
            return isinstance(other, TInt)

        def __hash__(self):
            return 0

        def __repr__(self):
            return "Int"

    class TBool(Type):
        def __eq__(self, other):
            return isinstance(other, TBool)

        def __hash__(self):
            return 0

        def __repr__(self):
            return "Bool"

    def is_well_formed(term):
        if isinstance(term, int):
            return True
        elif term in (True, False):
            return True
        elif isinstance(term, str):
            return len(term) > 0
        elif isinstance(term, tuple):
            if len(term) == 0:
                return False
            head = term[0]
            if not isinstance(head, str):
                return False
            if head == "lam":
                if len(term) != 3:
                    return False
                x, body = term[1], term[2]
                return is_well_formed(x) and is_well_formed(body)
            elif head == "app":
                if len(term) != 3:
                    return False
                f, a = term[1], term[2]
                return is_well_formed(f) and is_well_formed(a)
            elif head == "if":
                if len(term) != 4:
                    return False
                c, t, e = term[1], term[2], term[3]
                return is_well_formed(c) and is_well_formed(t) and is_well_formed(e)
            elif head == "let":
                if len(term) != 4:
                    return False
                x, e1, e2 = term[1], term[2], term[3]
                return is_well_formed(x) and is_well_formed(e1) and is_well_formed(e2)
            elif head == "letrec":
                if len(term) != 3:
                    return False
                group, body = term[1], term[2]
                if not isinstance(group, tuple) or len(group) == 0:
                    return False
                names = set()
                for pair in group:
                    if not isinstance(pair, tuple) or len(pair) != 2:
                        return False
                    name, expr = pair
                    if not isinstance(name, str) or len(name) == 0:
                        return False
                    if name in names:
                        return False
                    names.add(name)
                    if not is_well_formed(expr):
                        return False
                return is_well_formed(body)
            elif head == "tuple":
                if len(term) == 1:
                    return True  # n=0
                elif len(term) >=3:
                    return all(is_well_formed(e) for e in term[1:])
                else:
                    return False  # n=1 or invalid
            elif head == "proj":
                if len(term) != 4:
                    return False
                i, n, e = term[1], term[2], term[3]
                if not (isinstance(i, int) and not isinstance(i, bool)):
                    return False
                if not (isinstance(n, int) and not isinstance(n, bool)):
                    return False
                if n < 2 or i < 0 or i >= n:
                    return False
                return is_well_formed(e)
            else:
                return False
        else:
            return False

    def var_name(n):
        name = []
        while n >= 0:
            name.append(n % 26)
            n = n // 26 - 1
        return ''.join(chr(ord('a') + c) for c in reversed(name))

    def fresh_var(counter):
        var = TVar(var_name(counter[0]))
        counter[0] += 1
        return var

    def instantiate(scheme, subst, counter):
        vars, typ = scheme
        for v in vars:
            new_var = fresh_var(counter)
            subst[v] = new_var
        return typ

    def free_vars(t, subst):
        if isinstance(t, TVar):
            if t.name in subst:
                return free_vars(subst[t.name], subst)
            return {t.name}
        elif isinstance(t, TArrow):
            return free_vars(t.a, subst) | free_vars(t.b, subst)
        elif isinstance(t, TList):
            return free_vars(t.a, subst)
        elif isinstance(t, TTuple):
            res = set()
            for e in t.elements:
                res |= free_vars(e, subst)
            return res
        else:
            return set()

    def generalize(t, env, subst):
        fvs = free_vars(t, subst)
        env_fvs = set()
        for v in env.values():
            env_fvs |= free_vars(v[1], subst)
        quantified = list(fvs - env_fvs)
        return (quantified, t)

    def unify(t1, t2, subst):
        t1 = apply_subst(t1, subst)
        t2 = apply_subst(t2, subst)

        if isinstance(t1, TVar):
            if t1.name in subst:
                return unify(subst[t1.name], t2, subst)
            elif isinstance(t2, TVar):
                if t1 == t2:
                    return subst
                subst[t1.name] = t2
                return subst
            else:
                subst[t1.name] = t2
                return subst
        elif isinstance(t2, TVar):
            return unify(t2, t1, subst)
        elif isinstance(t1, TArrow) and isinstance(t2, TArrow):
            subst = unify(t1.a, t2.a, subst)
            subst = unify(t1.b, t2.b, subst)
            return subst
        elif isinstance(t1, TList) and isinstance(t2, TList):
            return unify(t1.a, t2.a, subst)
        elif isinstance(t1, TTuple) and isinstance(t2, TTuple):
            if len(t1.elements) != len(t2.elements):
                raise ValueError("Tuple length mismatch")
            for a, b in zip(t1.elements, t2.elements):
                subst = unify(a, b, subst)
            return subst
        elif isinstance(t1, TInt) and isinstance(t2, TInt):
            return subst
        elif isinstance(t1, TBool) and isinstance(t2, TBool):
            return subst
        else:
            raise ValueError("Cannot unify")

    def apply_subst(t, subst):
        if isinstance(t, TVar):
            if t.name in subst:
                return apply_subst(subst[t.name], subst)
            return t
        elif isinstance(t, TArrow):
            return TArrow(apply_subst(t.a, subst), apply_subst(t.b, subst))
        elif isinstance(t, TList):
            return TList(apply_subst(t.a, subst))
        elif isinstance(t, TTuple):
            elements = [apply_subst(e, subst) for e in t.elements]
            return TTuple(*elements)
        else:
            return t

    def infer(term, env, subst, counter):
        if isinstance(term, int):
            return TInt(), subst
        elif term is True or term is False:
            return TBool(), subst
        elif isinstance(term, str):
            if term not in env:
                raise ValueError(f"Unbound variable {term}")
            scheme = env[term]
            typ = instantiate(scheme, subst, counter)
            return typ, subst
        elif isinstance(term, tuple):
            head = term[0]
            if head == "lam":
                x, body = term[1], term[2]
                var = fresh_var(counter)
                new_env = dict(env)
                new_env[x] = ([], var)
                body_type, subst = infer(body, new_env, subst, counter)
                return TArrow(var, body_type), subst
            elif head == "app":
                f, a = term[1], term[2]
                f_type, subst = infer(f, env, subst, counter)
                a_type, subst = infer(a, env, subst, counter)
                res_var = fresh_var(counter)
                subst = unify(f_type, TArrow(a_type, res_var), subst)
                return apply_subst(res_var, subst), subst
            elif head == "if":
                c, t, e = term[1], term[2], term[3]
                c_type, subst = infer(c, env, subst, counter)
                subst = unify(c_type, TBool(), subst)
                t_type, subst = infer(t, env, subst, counter)
                e_type, subst = infer(e, env, subst, counter)
                subst = unify(t_type, e_type, subst)
                return apply_subst(t_type, subst), subst
            elif head == "let":
                x, e1, e2 = term[1], term[2], term[3]
                e1_type, subst = infer(e1, env, subst, counter)
                scheme = generalize(e1_type, env, subst)
                new_env = dict(env)
                new_env[x] = scheme
                return infer(e2, new_env, subst, counter)
            elif head == "letrec":
                group, body = term[1], term[2]
                temp_env = dict(env)
                for name, expr in group:
                    temp_env[name] = ([], fresh_var(counter))
                subst_group = subst.copy()
                for name, expr in group:
                    expr_type, subst_group = infer(expr, temp_env, subst_group, counter)
                for name, expr in group:
                    expr_type = apply_subst(expr_type, subst_group)
                    scheme = generalize(expr_type, env, subst_group)
                    temp_env[name] = scheme
                return infer(body, temp_env, subst_group, counter)
            elif head == "tuple":
                elements = term[1:]
                types = []
                for e in elements:
                    t, subst = infer(e, env, subst, counter)
                    types.append(t)
                return TTuple(*types), subst
            elif head == "proj":
                i, n, e = term[1], term[2], term[3]
                e_type, subst = infer(e, env, subst, counter)
                subst = unify(e_type, TTuple(*[fresh_var(counter) for _ in range(n)]), subst)
                proj_type = apply_subst(e_type.elements[i], subst)
                return proj_type, subst
            else:
                raise ValueError("Unknown form")
        else:
            raise ValueError("Malformed term")

    def type_to_str(t, subst):
        t = apply_subst(t, subst)
        if isinstance(t, TVar):
            return t.name
        elif isinstance(t, TArrow):
            return f" (-> {type_to_str(t.a, subst)} {type_to_str(t.b, subst)})"
        elif isinstance(t, TList):
            return f"(List {type_to_str(t.a, subst)})"
        elif isinstance(t, TTuple):
            if len(t.elements) == 0:
                return "(Tuple)"
            else:
                elements_str = " ".join(type_to_str(e, subst) for e in t.elements)
                return f"(Tuple {elements_str})"
        elif isinstance(t, TInt):
            return "Int"
        elif isinstance(t, TBool):
            return "Bool"
        else:
            raise ValueError("Unknown type")

    if not is_well_formed(term):
        raise ValueError("Malformed term")

    initial_env = {
        'add': ([], TArrow(TInt(), TArrow(TInt(), TInt()))),
        'eq': (['a'], TArrow(TVar('a'), TArrow(TVar('a'), TBool()))),
        'nil': (['a'], TList(TVar('a'))),
        'cons': (['a'], TArrow(TVar('a'), TArrow(TList(TVar('a')), TList(TVar('a'))))),
        'head': (['a'], TArrow(TList(TVar('a')), TVar('a'))),
        'tail': (['a'], TArrow(TList(TVar('a')), TList(TVar('a')))),
        'isnil': (['a'], TArrow(TList(TVar('a')), TBool()))
    }

    subst = {}
    counter = [0]

    try:
        typ, subst = infer(term, initial_env, subst, counter)
        return type_to_str(typ, subst)
    except Exception as e:
        raise ValueError(str(e))

