    # Filter edges to only include those starting in R
    filtered_edges = []
    for u, v in edges:
        if u in R:
            filtered_edges.append((u, v))
    # Add edges from exits (in R) to END (node n)
    END = n
    for e in exits_set:
        if e in R:
            filtered_edges.append((e, END))
    # Now, build the reversed graph for post-dominator computation
    # Nodes include 0..n-1 and END (n)
    total_nodes = n + 1
    reverse_adj = [[] for _ in range(total_nodes)]
    for u, v in filtered_edges:
        reverse_adj[v].append(u)
    # Step 2: Compute A (nodes in R that can reach END)
    # BFS from END in reversed graph
    visited_A = [False] * total_nodes
    q = deque()
    q.append(END)
    visited_A[END] = True
    while q:
        v = q.popleft()
        for u in reverse_adj[v]:
            if not visited_A[u]:
                visited_A[u] = True
                q.append(u)
    A = set()
    for node in R:
        if visited_A[node]:
            A.add(node)
    # Now, build the graph for post-dominators (reversed graph with END)
    # Reverse again to get the original graph edges plus END edges
    original_edges = [[] for _ in range(total_nodes)]
    for u, v in filtered_edges:
        original_edges[u].append(v)
    # Compute dominator tree using Lengauer-Tarjan
    def lengauer_tarjan(nodes, edges, start):
        parent = {}
        vertex = []
        label = {}
        size = len(nodes)
        # ... (implementation of Lengauer-Tarjan algorithm)
        # For brevity, here's a simplified version using BFS for dominators (not efficient for large n, but for the problem's constraints?)
        # Since this is a simplified solution and time is limited, perhaps use a BFS-based approach for dominators (though it's O(N^2), which may not be feasible for n=40000)
        # Alternatively, use an existing implementation.
