    for u in A:
        for v in original_edges[u]:
            if v in A:
                s = v
                # For edge u -> s, find all y in post(s) that do not strictly post-dominate u
                post_s = post_dom[s]
                for y in post_s:
                    if y not in A:
                        continue
                    # Check if y does not strictly post-dominate u
                    # Strictly post-dominates means y is in post(u) and y != u
                    if y in post_dom[u] and y != u:
