    # We need to traverse from T to collect all nodes x where some node in T or C is control dependent on x
    # So, the graph edges are y -> x if y is control dependent on x
    # To compute the closure, we can use BFS/DFS starting from T
    visited_C = set()
    q = deque()
    for t in T:
        q.append(t)
        visited_C.add(t)
    while q:
        y = q.popleft()
        for x in control_deps[y]:
            if x not in visited_C:
                visited_C.add(x)
                q.append(x)
    C = visited_C
    # Prepare the output
    sorted_C = sorted(C)
    sorted_targets_not_in_A = sorted(targets_not_in_A)
    return (sorted_C, sorted_targets_not_in_A)

import sys
from collections import deque

def branch_influence(n, edges, entry, exits, targets):
    # Validate inputs
    if not isinstance(n, int) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or not (0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    for u, v in edges:
        if not isinstance(u, int) or not (0 <= u < n):
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
        if not isinstance(v, int) or not (0 <= v < n):
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
    for e in exits:
        if not isinstance(e, int) or not (0 <= e < n):
            raise ValueError("exits must be a list of ints in 0..n-1")
    for t in targets:
        if not isinstance(t, int) or not (0 <= t < n):
            raise ValueError("targets must be a list of ints in 0..n-1")

    # Step 1: Compute R (nodes reachable from entry)
    R = set()
    stack = [entry]
    R.add(entry)
    while stack:
        u = stack.pop()
        for v in [e[1] for e in edges if e[0] == u]:
            if v not in R:
                R.add(v)
                stack.append(v)

    # Step 2: Compute A (nodes in R that can reach any exit)
    # Build reversed graph to find nodes that can reach exits
    reverse_edges = [[] for _ in range(n)]
    for u, v in edges:
        if u in R and v in R:
            reverse_edges[v].append(u)

    # BFS from exits to find all nodes that can reach an exit (in original graph)
    exits_set = set(exits)
    A = set()
    queue = deque(exits_set)
    visited = {exit_node for exit_node in exits_set}
    A.update(exits_set)
    while queue:
        v = queue.popleft()
        for u in reverse_edges[v]:
            if u not in visited and u in R:
                visited.add(u)
                A.add(u)
                queue.append(u)

    # Step 3: Build the graph for post-dominance (reversed graph with END)
    # We'll use a virtual node for END (represented as n)
    # Create reversed graph for dominators (END is start node)
    # Nodes in A are 0..n-1, END is n
    size = n + 1
    reversed_edges_for_dominators = [[] for _ in range(size)]
    for u, v in edges:
        if u in A and v in A:
            reversed_edges_for_dominators[v].append(u)
    # Add edges from exits to END (so in reversed graph, END has edges to exits)
    for exit_node in exits:
        if exit_node in A:
            reversed_edges_for_dominators[exit_node].append(n)

    # Compute dominators using Lengauer-Tarjan algorithm
    def compute_dominators(start, size, edges_list):
        parent = [0] * size
        semi = [0] * size
        ancestor = [0] * size
        vertex = [0] * size
        label = [0] * size
        bucket = [[] for _ in range(size)]
        dom = [0] * size

        def compress(u):
            while ancestor[u] != 0:
                v = ancestor[u]
                if semi[v] > semi[u]:
                    semi[u] = semi[v]
                    label[u] = label[v]
                ancestor[u] = ancestor[v]
                u = v
            return u

        def dfs(u):
            nonlocal time
            time += 1
            vertex[time] = u
            semi[u] = time
            for v in edges_list[u]:
                if semi[v] == 0:
                    parent[v] = u
                    dfs(v)
                else:
                    compress(v)
                    if semi[v] < semi[u]:
                        semi[u] = semi[v]

        def eval(u):
            if semi[u] != semi[label[u]]:
                label[u] = eval(label[u])
            return label[u]

        time = 0
        dfs(start)
        for i in range(time, 0, -1):
            u = vertex[i]
            for v in bucket[u]:
                w = eval(v)
                if semi[w] < semi[v]:
                    dom[v] = w
                else:
                    dom[v] = u
            bucket[parent[u]].append(u)
            if u != parent[u]:
                ancestor[u] = parent[u]
        for i in range(2, time + 1):
            u = vertex[i]
            if dom[u] != parent[u]:
                dom[u] = dom[dom[u]]
        return dom

    # Start node is END (n)
    dominators = compute_dominators(n, size, reversed_edges_for_dominators)

    # Compute post-dominators for each node in A (excluding END)
    post_dominators = {}
    for u in A:
        pd = set()
        current = u
        while current != 0:
            pd.add(current)
            current = dominators[current]
        post_dominators[u] = pd

    # Step 4: Find control dependencies
    control_deps = {}  # x -> list of y such that y is control dependent on x
    for u in A:
        control_deps[u] = []

    # Iterate over all edges in original graph (within R and A)
    for u, v in edges:
        if u not in A or v not in A:
            continue
        s = v
        # Find all y in A such that y post-dominates s and does not strictly post-dominate u
        pd_s = post_dominators[s]
        pd_u = post_dominators[u]
        for y in pd_s:
            if y not in pd_u or (y in pd_u and y == u):
                # Check if y strictly post-dominates u?
                # Strictly post-dominates means y is in pd_u and y != u
                # So y must not be in pd_u or (y is in pd_u and y == u)
                # Wait, the condition is: y does not strictly post-dominate u
                # Which is equivalent to: either y is not in pd_u, or y is in pd_u and y == u
                control_deps[u].append(y)

    # Step 5: Compute T (targets in A)
    T = set()
    for t in targets:
        if t in A:
            T.add(t)

    # Step 6: Compute C as the closure of nodes x where some node in T or C is control dependent on x
    C = set()
    # Initialize with targets
    queue = deque(T)
    C.update(T)
    while queue:
        y = queue.popleft()
        # Find all x where y is control dependent on x
        for x in control_deps:
            if y in control_deps[x]:
                if x not in C:
                    C.add(x)
                    queue.append(x)

