    for u, v in edges:
        adj[u].append(v)
        pred[v].append(u)

    parent = [None] * n
    post_order = [0] * n
    time = 0
    visited = [False] * n
    stack = [(entry, False)]

    while stack:
        node, processed = stack.pop()
        if processed:
            post_order[node] = time
            time += 1
            continue
        if visited[node]:
            continue
        visited[node] = True
        stack.append((node, True))
        for neighbor in reversed(adj[node]):
            if not visited[neighbor]:
                parent[neighbor] = node
                stack.append((neighbor, False))

