        for v in pred[u]:
            if post_order[v] < post_order[u]:
                if sdom[u] > sdom[v]:
                    sdom[u] = sdom[v]
        w = find(u)
        if sdom[u] > sdom[w]:
            sdom[u] = sdom[w]
        ancestor[u] = parent[u]

    idom = [0] * n
    for u in nodes:
        if u == entry:
            idom[u] = entry
            continue
        v = find(u)
        if sdom[v] == sdom[u]:
            idom[u] = v
        else:
            idom[u] = idom[v]

    return idom

