    # Step 2: Compute dominator tree using Lengauer-Tarjan algorithm
    # Implement Lengauer-Tarjan algorithm
    def compute_dominators(n, adj, start):
        # Precompute the post-order number
        parent = [ -1 ] * n
        post_order = []
        visited = [False] * n
        stack = [(start, False)]
        while stack:
            node, processed = stack.pop()
            if processed:
                post_order.append(node)
                continue
            if visited[node]:
                continue
            visited[node] = True
            stack.append((node, True))
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    parent[neighbor] = node
                    stack.append((neighbor, False))

        # Initialize
        size = len(post_order)
        vertex = [0] * n
        for i, v in enumerate(post_order):
            vertex[v] = i

        semi = [i for i in range(size)]
        ancestor = [0] * size
        label = list(range(size))
        parent_semi = [0] * size
        dfn = [0] * n  # post_order index for each node

        for i in range(size):
            dfn[post_order[i]] = i

        # Function to find ancestor with minimum semi
        def find(u):
            if ancestor[u] != u:
                ancestor[u] = find(ancestor[u])
                if semi[label[ancestor[u]]] < semi[label[u]]:
                    label[u] = label[ancestor[u]]
            return label[u]

        # Process nodes in reverse post-order (excluding start)
        for i in reversed(range(size)):
            v = post_order[i]
            if v == start:
                continue
            for u in adj[v]:
                if dfn[u] < dfn[v]:
                    if dfn[u] < dfn[find(dfn[u])]:
                        semi[i] = dfn[u]
                else:
                    ancestor[dfn[u]] = i
            s = semi[i]
            if s != i:
                label[i] = find(s)
            parent_semi[i] = post_order[s]

        # Compute immediate dominators
        idom = [ -1 ] * n
        idom[start] = -1  # entry has no idom
        for i in range(size):
            if i == 0:
                continue  # start node
            v = post_order[i]
            if semi[i] == i:
                idom[v] = parent_semi[i]
            else:
                idom[v] = idom[label[semi[i]]]

        return idom

    # Compute idom for all nodes
    idom = compute_dominators(n, adj, entry)

    # Build dominator tree
    dom_tree = defaultdict(list)
    for v in reachable:
        if idom[v] != -1:
            dom_tree[idom[v]].append(v)

    # Step 3: Compute LCA for dominator tree
    LOG = 20  # sufficient for n up to 40,000
    up = [[-1]*n for _ in range(LOG)]
    depth = [0]*n

    # Build up table for binary lifting
    for u in reachable:
        up[0][u] = idom[u] if idom[u] != -1 else -1

    for k in range(1, LOG):
        for u in reachable:
            if up[k-1][u] != -1:
                up[k][u] = up[k-1][up[k-1][u]]
            else:
                up[k][u] = -1

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        # Bring u to the depth of v
        for k in range(LOG-1, -1, -1):
            if depth[u] - (1 << k) >= depth[v]:
                u = up[k][u]
        if u == v:
            return u
        for k in range(LOG-1, -1, -1):
            if up[k][u] != -1 and up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    # Compute depth for each node
    for u in reachable:
        current = u
        d = 0
        while current != entry:
            current = idom[current]
            d += 1
        depth[u] = d

    # Step 4: Compute dominance frontiers for each node
    df = defaultdict(set)

    for (p, y) in filtered_edges:
        L = lca(p, y)
        path = []
        current = p
        while current != L:
            path.append(current)
            current = idom[current]
        for d in path:
            df[d].add(y)
        if L == y:
            df[y].add(y)

    # Step 5: Compute D(x) and P(x) for each variable x
    # First, collect all variables
    all_vars = set()
    for node in blocks:
        for (op, x) in blocks[node]:
            all_vars.add(x)
    all_vars.update(params)
    all_vars = list(all_vars)

    # D(x) is set of nodes with def/upd of x plus entry if x in params
    D = defaultdict(set)
    for x in all_vars:
        if x in params:
            D[x].add(entry)
        for node in blocks:
            for (op, var) in blocks[node]:
                if var == x and op in ('def', 'upd'):
                    D[x].add(node)

    # Compute P(x) as the closure under DF
    P = defaultdict(set)
    for x in all_vars:
        P[x] = set(D[x])
        changed = True
        while changed:
            changed = False
            new_nodes = set()
            for d in P[x]:
                new_nodes.update(df[d])
            for y in new_nodes:
                if y not in P[x]:
                    P[x].add(y)
                    changed = True

    # Step 6: Compute live-in for each node and variable
    # First, collect upward exposed uses
    exposed_uses = defaultdict(set)
    for node in reachable:
        instr_list = blocks.get(node, [])
        has_def_before = False
        for instr in instr_list:
            op, x = instr
            if op in ('def', 'upd'):
                has_def_before = True
            elif op == 'use':
                if not has_def_before:
                    exposed_uses[x].add(node)
            else:
                assert False, "unknown op"

    # Build reverse adjacency list
    reverse_adj = defaultdict(list)
    for u in reachable:
        for v in adj[u]:
            reverse_adj[v].append(u)

    # Compute live_in_x for each x
    live_in_x = defaultdict(set)
    for x in all_vars:
        start_nodes = exposed_uses[x]
        if not start_nodes:
            continue
        def_nodes = D[x]
        visited = set()
        queue = deque()
        for w in start_nodes:
            if w not in visited:
                visited.add(w)
                queue.append(w)
        while queue:
            v = queue.popleft()
            for u in reverse_adj[v]:
                if u not in visited and u not in def_nodes:
                    visited.add(u)
                    queue.append(u)
        live_in_x[x] = visited

    # Step 7: Collect results
    result = []
    for node in sorted(reachable):
        vars_needed = []
        for x in sorted(all_vars):
            if node in P[x] and node in live_in_x[x]:
                vars_needed.append(x)
        if vars_needed:
            result.append((node, vars_needed))
    return result

import sys
from collections import defaultdict, deque

def live_phi_sites(n, edges, entry, blocks, params):
    # Validate inputs
    if not isinstance(n, int) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or not (0 <= entry < n):
        raise ValueError("entry must be in 0..n-1")
    if any(len(e) != 2 or not all(isinstance(x, int) and 0 <= x < n for x in e) for e in edges):
        raise ValueError("edges must be pairs of ints in 0..n-1")
    for node in blocks:
        if not isinstance(node, int) or not (0 <= node < n):
            raise ValueError("blocks keys must be ints in 0..n-1")
        for instr in blocks[node]:
            if not (isinstance(instr, (list, tuple)) and len(instr) == 2):
                raise ValueError("instructions must be pairs")
            op, x = instr
            if op not in ("use", "def", "upd") or not isinstance(x, str) or not x:
                raise ValueError("invalid instruction")
    if not all(isinstance(p, str) and p for p in params):
        raise ValueError("params must be non-empty strings")

    # Step 1: Find reachable nodes from entry
    reachable = set()
    q = deque([entry])
    while q:
        u = q.popleft()
        if u in reachable:
            continue
        reachable.add(u)
        for (a, b) in edges:
            if a == u and b not in reachable:
                q.append(b)

    # Filter edges to reachable nodes
    filtered_edges = []
    for (u, v) in edges:
        if u in reachable and v in reachable:
            filtered_edges.append((u, v))

    # Build adjacency list for reachable nodes (successors)
    adj = defaultdict(list)
    for u, v in filtered_edges:
        adj[u].append(v)

    # Build predecessor adjacency list (predecessors)
    pred_adj = defaultdict(list)
    for u in adj:
        for v in adj[u]:
            pred_adj[v].append(u)

    # Step 2: Compute dominator tree using Lengauer-Tarjan algorithm
    def compute_dominators(n, pred_adj, start):
        parent = [-1] * n
        post_order = []
        visited = [False] * n
        stack = [(start, False)]
        while stack:
            node, processed = stack.pop()
            if processed:
                post_order.append(node)
                continue
            if visited[node]:
                continue
            visited[node] = True
            stack.append((node, True))
            for neighbor in pred_adj[node]:
                if not visited[neighbor]:
                    parent[neighbor] = node
                    stack.append((neighbor, False))

        size = len(post_order)
        vertex = [0] * n
        for i, v in enumerate(post_order):
            vertex[v] = i

        semi = list(range(size))
        ancestor = [0] * size
        label = list(range(size))
        parent_semi = [0] * size
        dfn = [0] * n

        for i in range(size):
            dfn[post_order[i]] = i

        def find(u):
            if ancestor[u] != u:
                ancestor[u] = find(ancestor[u])
                if semi[label[ancestor[u]]] < semi[label[u]]:
                    label[u] = label[ancestor[u]]
            return label[u]

        for i in reversed(range(size)):
            v = post_order[i]
            if v == start:
                continue
            for u in pred_adj[v]:
                if dfn[u] < dfn[v]:
                    if dfn[u] < dfn[find(dfn[u])]:
                        semi[i] = dfn[u]
                else:
                    ancestor[dfn[u]] = i
            s = semi[i]
            if s != i:
                label[i] = find(s)
            parent_semi[i] = post_order[s]

        idom = [-1] * n
        idom[start] = -1
        for i in range(size):
            if i == 0:
                continue
            v = post_order[i]
            if semi[i] == i:
                idom[v] = parent_semi[i]
            else:
                idom[v] = idom[label[semi[i]]]

        return idom

    # Compute idom for all nodes
    idom = compute_dominators(n, pred_adj, entry)

    # Build dominator tree and compute depth
    dom_tree = defaultdict(list)
    for v in reachable:
        if idom[v] != -1:
            dom_tree[idom[v]].append(v)

    LOG = 20
    depth = [0] * n
    queue = deque([entry])
    depth[entry] = 0
    while queue:
        u = queue.popleft()
        for v in dom_tree[u]:
            depth[v] = depth[u] + 1
            queue.append(v)

    # Precompute binary lifting table for LCA
    up = [[-1] * n for _ in range(LOG)]
    for u in reachable:
        up[0][u] = idom[u] if idom[u] != -1 else -1

    for k in range(1, LOG):
        for u in reachable:
            if up[k-1][u] != -1:
                up[k][u] = up[k-1][up[k-1][u]]
            else:
                up[k][u] = -1

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        # Bring u to the depth of v
        for k in range(LOG-1, -1, -1):
            if depth[u] - (1 << k) >= depth[v]:
                u = up[k][u]
        if u == v:
            return u
        for k in range(LOG-1, -1, -1):
            if up[k][u] != -1 and up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    # Step 4: Compute dominance frontiers for each node
    df = defaultdict(set)

    for (p, y) in filtered_edges:
        L = lca(p, y)
        current = p
        while current != L:
            df[current].add(y)
            current = idom[current]
        if L == y:
            df[L].add(y)

    # Step 5: Compute D(x) and P(x) for each variable x
    all_vars = set()
    for node in blocks:
        for (op, x) in blocks[node]:
            all_vars.add(x)
    all_vars.update(params)
    all_vars = list(all_vars)

    D = defaultdict(set)
    for x in all_vars:
        if x in params:
            D[x].add(entry)
        for node in blocks:
            for (op, var) in blocks[node]:
                if var == x and op in ('def', 'upd'):
                    D[x].add(node)

    # Compute P(x) using worklist approach
    P = defaultdict(set)
    for x in all_vars:
        P[x] = set(D[x])
        worklist = deque(D[x])
        while worklist:
            d = worklist.popleft()
            for y in df[d]:
                if y not in P[x]:
                    P[x].add(y)
                    worklist.append(y)

    # Step 6: Compute live-in for each node and variable
    exposed_uses = defaultdict(set)
    for node in reachable:
        instr_list = blocks.get(node, [])
        has_def_before = False
        for instr in instr_list:
            op, x = instr
            if op in ('def', 'upd'):
                has_def_before = True
            elif op == 'use':
                if not has_def_before:
                    exposed_uses[x].add(node)

    reverse_adj = defaultdict(list)
    for u in adj:
        for v in adj[u]:
            reverse_adj[v].append(u)

    live_in_x = defaultdict(set)
    for x in all_vars:
        start_nodes = exposed_uses[x]
        if not start_nodes:
            continue
        def_nodes = D[x]
        visited = set()
        queue = deque()
        for w in start_nodes:
            if w not in visited:
                visited.add(w)
                queue.append(w)
        while queue:
            v = queue.popleft()
            for u in reverse_adj[v]:
                if u not in visited and u not in def_nodes:
                    visited.add(u)
                    queue.append(u)
        live_in_x[x] = visited

    # Step 7: Collect results
    result = []
    for node in sorted(reachable):
        vars_needed = []
        for x in sorted(all_vars):
            if node in P[x] and node in live_in_x[x]:
                vars_needed.append(x)
        if vars_needed:
            result.append((node, vars_needed))
    return result

def format_sigfigs(s, sig, mode):
    # Check input validity
    if not isinstance(s, str) or not isinstance(sig, int) or not isinstance(mode, str):
        raise ValueError("Invalid input types")
    if sig < 1 or sig > 2000 or isinstance(sig, bool):
        raise ValueError("Invalid sig")
    valid_modes = {"nearest_even", "nearest_away", "nearest_zero", "toward_zero",
                   "away_zero", "toward_neg", "toward_pos", "zero_five"}
    if mode not in valid_modes:
        raise ValueError("Invalid mode")

    # Parse the input string
    if len(s) > 100000:
        raise ValueError("Input too long")

    sign = ''
    if s and s[0] in '+-':
        sign = s[0]
        s_rest = s[1:]
    else:
        s_rest = s

    # Split into mantissa and exponent parts
    e_pos = s_rest.lower().find('e')
    if e_pos != -1:
        mantissa_str = s_rest[:e_pos]
        exponent_str = s_rest[e_pos+1:]
    else:
        mantissa_str = s_rest
        exponent_str = None

    # Parse exponent
    exponent = 0
    if exponent_str is not None:
        if exponent_str[0] in '+-':
            exp_sign = exponent_str[0]
            exp_num = exponent_str[1:]
        else:
            exp_sign = '+'
            exp_num = exponent_str
        if len(exp_num) < 1 or len(exp_num) > 10:
            raise ValueError("Invalid exponent")
        exponent = int(exp_sign + exp_num)

    # Process mantissa
    if not mantissa_str:
        raise ValueError("Invalid mantissa")

    # Remove decimal point and track its position
    dec_pos = mantissa_str.find('.')
    if dec_pos != -1:
        digits_str = mantissa_str.replace('.', '')
    else:
        digits_str = mantissa_str
        dec_pos = len(digits_str)  # Decimal is after the last digit

    # Check if all digits are zero
    all_zero = all(c == '0' for c in digits_str)
    if all_zero:
        # Handle zero case
        if sig == 1:
            return "0e+00"
        else:
            return "0." + "0"*(sig-1) + "e+00"

    # Find first non-zero digit position
    first_pos = -1
    for i, c in enumerate(digits_str):
        if c != '0':
            first_pos = i
            break
    if first_pos == -1:
        return "0e+00"  # Shouldn't happen since all_zero is false

    # Calculate exponent contribution from mantissa
    num_after_dec = len(digits_str) - dec_pos - 1
    exponent_mantissa = -num_after_dec
    total_exponent = exponent + exponent_mantissa

    # Extract significant digits
    significant = digits_str[first_pos:]
    len_sig = len(significant)

    if len_sig <= sig:
        # Pad with zeros if needed
        padded = significant.ljust(sig, '0')
    else:
        # Need to round
        kept = list(significant[:sig])
        dropped = significant[sig:]
        # Determine rounding
        need_round = any(c != '0' for c in dropped)

        def get_round_value():
            if mode == "toward_zero":
                return False
            elif mode == "away_zero":
                return True
            elif mode == "toward_neg":
                return sign == '-' and need_round
            elif mode == "toward_pos":
                return sign != '-' and need_round
            elif mode in ["nearest_even", "nearest_away", "nearest_zero"]:
                # Check if exactly halfway
                half = '5' + '0' * (len(dropped) -1)
                if dropped > half:
                    return True
                elif dropped < half:
                    return False
                else:
                    # Exactly half
                    if mode == "nearest_even":
                        return int(kept[-1]) % 2 == 1
                    elif mode == "nearest_away":
                        return True
                    else:  # nearest_zero
                        return False
            elif mode == "zero_five":
                if need_round:
                    last_digit = int(kept[-1])
                    if last_digit in (0,5):
                        return True
                return False

        if need_round and get_round_value():
            # Increment the last digit
            carry = 1
            for i in reversed(range(len(kept))):
                new_d = int(kept[i]) + carry
                if new_d == 10:
                    kept[i] = '0'
                    carry = 1
                else:
                    kept[i] = str(new_d)
                    carry = 0
                    break
            if carry:
                # All digits were 9's, so we need to carry over
                kept = ['1'] + ['0'] * (sig-1)
                total_exponent += 1
        padded = ''.join(kept)

    # Handle the case where rounding caused a carryover that increases the exponent
    first_digit = padded[0]
    if first_digit == '0':
        # Shouldn't happen since we have non-zero
        return "0e+00"

    # Build the result
    result = []
    result.append(first_digit)
    if sig > 1:
        result.append('.')
        result.append(padded[1:])
    result.append('e')
    if total_exponent >= 0:
        result.append('+')
        result.append(f"{total_exponent:02d}")
    else:
        result.append('-')
        result.append(f"{abs(total_exponent):02d}")

    res_str = ''.join(result)

    # Check exponent range
    exp = total_exponent
    if exp < -999999999 or exp > 999999999:
        raise ValueError("Exponent out of range")

    return res_str

