def snap_to_step(x_str, step_str, mode):
    def parse(s):
        if len(s) > 4000:
            raise ValueError("Input too long")
        sign = 1
        if s[0] in '+-':
            sign = -1 if s[0] == '-' else 1
            s = s[1:]
        has_e = 'e' in s or 'E' in s
        if has_e:
            parts = s.lower().split('e')
            s = parts[0]
            exp_str = parts[1]
            if exp_str[0] in '+-':
                exp_sign = -1 if exp_str[0] == '-' else 1
                exp_str = exp_str[1:]
            else:
                exp_sign = 1
            exp = int(exp_str) * exp_sign
        else:
            exp = 0
        if '.' in s:
            parts = s.split('.')
            int_part, frac_part = parts[0], parts[1] if len(parts) > 1 else ''
            mantissa = int(int_part + frac_part)
            exp -= len(frac_part)
        else:
            mantissa = int(s)
        return (sign, mantissa, exp)

    def to_common_exp(x, step):
        x_sign, x_m, x_e = x
        step_sign, step_m, step_e = step
        assert step_sign == 1, "Step must be positive"
        delta_e = x_e - step_e
        if delta_e >= 0:
            num = x_sign * x_m * (10 ** delta_e)
            den = step_m
        else:
            num = x_sign * x_m
            den = step_m * (10 ** (-delta_e))
        return (num, den)

    def compute_k(num, den, mode, x_sign):
        q, rem = divmod(num, den)
        if rem == 0:
            return q
        if mode == "floor":
            return q
        elif mode == "ceil":
            return q + 1
        elif mode == "outward":
            if x_sign > 0:
                if 2 * rem > den:
                    return q + 1
                elif 2 * rem < den:
                    return q
                else:
                    return q + 1 if q % 2 == 0 else q
            else:
                if 2 * rem > den:
                    return q - 1
                elif 2 * rem < den:
                    return q
                else:
                    return q - 1 if q % 2 == 0 else q
        elif mode == "inward":
            if x_sign > 0:
                if 2 * rem < den:
                    return q
                elif 2 * rem > den:
                    return q + 1
                else:
                    return q if q % 2 == 0 else q + 1
            else:
                if 2 * rem < den:
                    return q
                elif 2 * rem > den:
                    return q - 1
                else:
                    return q if q % 2 != 0 else q - 1
        elif mode == "tie_even":
            if 2 * rem == den:
                return q if q % 2 == 0 else q + 1
            else:
                return q + 1 if 2 * rem > den else q
        elif mode == "tie_odd":
            if 2 * rem == den:
                return q if q % 2 != 0 else q + 1
            else:
                return q + 1 if 2 * rem > den else q
        elif mode == "tie_away":
            if 2 * rem == den:
                return q + 1 if x_sign > 0 else q - 1
            else:
                return q + 1 if 2 * rem > den else q
        elif mode == "tie_zero":
            if 2 * rem == den:
                if x_sign > 0:
                    return q if abs(q + 0.5) < abs(q + 1) else q + 1
                else:
                    return q if abs(q - 0.5) < abs(q - 1) else q - 1
            else:
                return q + 1 if 2 * rem > den else q
        else:
            raise ValueError("Invalid mode")

    x = parse(x_str)
    step = parse(step_str)
    step_sign, step_m, step_e = step
    if step_m <= 0:
        raise ValueError("Step must be positive")
    if mode not in {"floor", "ceil", "outward", "inward", "tie_even", "tie_odd", "tie_away", "tie_zero"}:
        raise ValueError("Invalid mode")

    num, den = to_common_exp(x, step)
    k = compute_k(num, den, mode, x[0])

    # Compute the scaled value
    d = max(0, -step_e)
    e_step_plus_d = step_e + d
    scaled = k * step_m * (10 ** e_step_plus_d)

    # Now format scaled into the required string
    if scaled == 0:
        integer_part_str = '0'
        fractional_part_str = '0' * d
    else:
        abs_scaled = abs(scaled)
        abs_str = str(abs_scaled)
        if len(abs_str) < d:
            integer_part = '0'
            fractional_part = abs_str.zfill(d)
        else:
            integer_part = abs_str[:-d]
            fractional_part = abs_str[-d:]
        # Process integer part to remove leading zeros
        integer_part_str = integer_part.lstrip('0') or '0'
        fractional_part_str = fractional_part

    # Determine the sign
    if scaled < 0:
        sign_str = '-'
    else:
        sign_str = ''

    # Build the result string
    if d == 0:
        result_str = sign_str + integer_part_str
    else:
        result_str = sign_str + integer_part_str + '.' + fractional_part_str

    # Handle the case when the result is zero (scaled is 0)
    if scaled == 0:
        result_str = '0' + ('.' + '0' * d if d > 0 else '')

    # Check for negative zero
    if result_str.startswith('-0') and len(result_str) > 1:
        if '.' in result_str:
            result_str = result_str[1:]
        else:
            result_str = '0'

    # Ensure no leading zeros in the integer part except for zero
    if '.' in result_str:
        parts = result_str.split('.')
        integer_part = parts[0]
        if integer_part == '':
            integer_part = '0'
        else:
            integer_part = integer_part.lstrip('0') or '0'
        result_str = f"{integer_part}.{parts[1]}"
    else:
        result_str = result_str.lstrip('0') or '0'

    # Ensure the fractional part has exactly d digits
    if '.' in result_str:
        parts = result_str.split('.')
        integer_part = parts[0]
        fractional_part = parts[1] if len(parts) > 1 else ''
        if len(fractional_part) != d:
